INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-4-02', 'ngsl-4', 'Thông dụng 1.501–2.000 · Bộ 2', 'New General Service List, thứ hạng 1.501–2.000', '#3da9fc', 'BookOpen', 2);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 1, 'expense', 'chi phí; phí tổn', 'noun', '[{"en":"Rent is our biggest expense every month.","vi":"Tiền thuê nhà là khoản chi phí lớn nhất của chúng tôi mỗi tháng."},{"en":"The company will cover all your travel expenses.","vi":"Công ty sẽ chi trả toàn bộ chi phí đi lại của bạn."},{"en":"We had to cut our living expenses after I lost my job.","vi":"Chúng tôi phải cắt giảm chi phí sinh hoạt sau khi tôi mất việc."}]', '[{"phrase":"travel expenses"},{"phrase":"living expenses"},{"phrase":"cover the expense"},{"phrase":"at the expense of"}]', NULL, '/ɪkˈspens/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expen/expense__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 2, 'channel', 'kênh (truyền hình); kênh (liên lạc, phân phối)', 'noun', '[{"en":"What channel is the football game on tonight?","vi":"Tối nay trận bóng đá chiếu trên kênh nào?"},{"en":"My dad keeps changing the channel during the ads.","vi":"Bố tôi cứ chuyển kênh mỗi khi có quảng cáo."},{"en":"Customers can contact us through several channels, including email and online chat.","vi":"Khách hàng có thể liên hệ với chúng tôi qua nhiều kênh, trong đó có email và trò chuyện trực tuyến."}]', '[{"phrase":"change the channel"},{"phrase":"TV channel"},{"phrase":"news channel"},{"phrase":"communication channels"}]', NULL, '/ˈtʃænl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chann/channel__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 3, 'investigate', 'điều tra; nghiên cứu, tìm hiểu', 'verb', '[{"en":"The police are investigating the cause of the fire.","vi":"Cảnh sát đang điều tra nguyên nhân vụ cháy."},{"en":"Scientists want to investigate how sleep affects memory.","vi":"Các nhà khoa học muốn nghiên cứu xem giấc ngủ ảnh hưởng đến trí nhớ như thế nào."},{"en":"I heard a strange noise, so I went downstairs to investigate.","vi":"Tôi nghe thấy một tiếng động lạ nên đi xuống nhà để tìm hiểu."}]', '[{"phrase":"investigate the cause"},{"phrase":"fully investigate"},{"phrase":"investigate a complaint"}]', NULL, '/ɪnˈvestɪɡeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/inves/investigate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 4, 'recommendation', 'lời gợi ý, đề xuất; sự giới thiệu', 'noun', '[{"en":"Do you have any recommendations for a good restaurant nearby?","vi":"Bạn có gợi ý nhà hàng nào ngon gần đây không?"},{"en":"The report makes several recommendations to improve safety at work.","vi":"Bản báo cáo đưa ra một số đề xuất nhằm cải thiện an toàn lao động."},{"en":"I bought this book on my teacher''s recommendation.","vi":"Tôi mua cuốn sách này theo lời giới thiệu của thầy giáo."}]', '[{"phrase":"make a recommendation"},{"phrase":"strong recommendation"},{"phrase":"letter of recommendation"},{"phrase":"on someone''s recommendation"}]', NULL, '/ˌrekəmenˈdeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recom/recommendation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 5, 'rank', 'xếp hạng; đứng (ở vị trí, thứ hạng)', 'verb', '[{"en":"The city is ranked among the safest places to live.","vi":"Thành phố này được xếp vào hàng những nơi an toàn nhất để sinh sống."},{"en":"Our university ranks third in the country for engineering.","vi":"Trường đại học của chúng tôi đứng thứ ba cả nước về ngành kỹ thuật."},{"en":"Please rank these five tasks from most to least important.","vi":"Hãy xếp năm nhiệm vụ này theo thứ tự từ quan trọng nhất đến ít quan trọng nhất."}]', '[{"phrase":"rank highly"},{"phrase":"rank first"},{"phrase":"rank among"}]', 'danh từ: rank = cấp bậc, thứ hạng', '/ræŋk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ran/rank_/rank__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 6, 'typical', 'điển hình; đặc trưng; thường thấy', 'adjective', '[{"en":"A typical day for me starts at six in the morning.","vi":"Một ngày điển hình của tôi bắt đầu lúc sáu giờ sáng."},{"en":"This hot, rainy weather is typical of the south in summer.","vi":"Thời tiết nóng và mưa nhiều thế này là đặc trưng của miền Nam vào mùa hè."},{"en":"It''s typical of him to arrive late and blame the traffic.","vi":"Đến muộn rồi đổ lỗi cho giao thông là chuyện thường thấy ở anh ta."}]', '[{"phrase":"typical example"},{"phrase":"typical day"},{"phrase":"typical of"},{"phrase":"fairly typical"}]', 'typical of sb/sth', '/ˈtɪpɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/typ/typic/typical__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 7, 'west', 'phía tây; hướng tây', 'noun', '[{"en":"The sun rises in the east and sets in the west.","vi":"Mặt trời mọc ở hướng đông và lặn ở hướng tây."},{"en":"My grandparents live in a small village in the west of the country.","vi":"Ông bà tôi sống ở một ngôi làng nhỏ phía tây đất nước."},{"en":"We drove west for three hours before stopping for lunch.","vi":"Chúng tôi lái xe về hướng tây ba tiếng rồi mới dừng lại ăn trưa."}]', '[{"phrase":"in the west"},{"phrase":"to the west of"},{"phrase":"head west"},{"phrase":"west coast"}]', NULL, '/west/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wes/west_/west__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 8, 'friendly', 'thân thiện; thân thiết', 'adjective', '[{"en":"The staff at the hotel were very friendly and helpful.","vi":"Nhân viên khách sạn rất thân thiện và nhiệt tình."},{"en":"She gave me a friendly smile when I walked in.","vi":"Cô ấy nở một nụ cười thân thiện với tôi khi tôi bước vào."},{"en":"We''ve been friendly with our neighbors for many years.","vi":"Chúng tôi đã thân thiết với hàng xóm nhiều năm nay."}]', '[{"phrase":"friendly smile"},{"phrase":"friendly staff"},{"phrase":"be friendly with"},{"phrase":"environmentally friendly"}]', 'friendly là tính từ, không phải trạng từ', '/ˈfrendli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fri/frien/friendly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 9, 'resident', 'cư dân; người sinh sống (ở một nơi)', 'noun', '[{"en":"Local residents are complaining about the noise from the new bar.","vi":"Cư dân địa phương đang phàn nàn về tiếng ồn từ quán bar mới."},{"en":"Parking on this street is for residents only.","vi":"Chỗ đỗ xe trên con phố này chỉ dành cho cư dân."},{"en":"She has been a resident of this town for twenty years.","vi":"Bà ấy đã sinh sống ở thị trấn này được hai mươi năm."}]', '[{"phrase":"local residents"},{"phrase":"resident of"},{"phrase":"permanent resident"}]', NULL, '/ˈrezɪdənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resid/resident__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 10, 'provision', 'sự cung cấp; điều khoản; lương thực dự trữ', 'noun', '[{"en":"The government is responsible for the provision of clean water.","vi":"Chính phủ chịu trách nhiệm về việc cung cấp nước sạch."},{"en":"The contract includes a provision for extra pay on holidays.","vi":"Hợp đồng có một điều khoản về việc trả thêm lương vào ngày lễ."},{"en":"The hikers carried enough provisions for a week in the mountains.","vi":"Những người leo núi mang đủ lương thực cho một tuần ở trên núi."}]', '[{"phrase":"provision of services"},{"phrase":"make provision for"},{"phrase":"legal provision"}]', 'nghĩa lương thực dự trữ thường dùng ở số nhiều: provisions', '/prəˈvɪʒn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/provi/provision__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 11, 'concentrate', 'tập trung', 'verb', '[{"en":"I can''t concentrate with all this noise outside.","vi":"Bên ngoài ồn ào thế này tôi không thể tập trung được."},{"en":"You should concentrate on your studies before the exam.","vi":"Bạn nên tập trung vào việc học trước kỳ thi."},{"en":"Most of the country''s population is concentrated in big cities.","vi":"Phần lớn dân số của đất nước tập trung ở các thành phố lớn."}]', '[{"phrase":"concentrate on"},{"phrase":"concentrate hard"},{"phrase":"find it hard to concentrate"}]', 'concentrate on sth', '/ˈkɑːnsntreɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconcentrate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 12, 'plenty', 'nhiều; dư dả', 'pronoun', '[{"en":"Don''t worry, we have plenty of time before the train leaves.","vi":"Đừng lo, chúng ta còn nhiều thời gian trước khi tàu chạy."},{"en":"Make sure you drink plenty of water in hot weather.","vi":"Nhớ uống thật nhiều nước khi trời nóng nhé."},{"en":"There''s no need to buy more eggs; we''ve got plenty.","vi":"Không cần mua thêm trứng đâu, nhà mình còn nhiều rồi."}]', '[{"phrase":"plenty of time"},{"phrase":"plenty of room"},{"phrase":"plenty of opportunities"}]', 'plenty of + danh từ đếm được hoặc không đếm được', '/ˈplenti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/ple/plent/plenty__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 13, 'export', 'xuất khẩu; xuất (tệp, dữ liệu)', 'verb', '[{"en":"Vietnam exports large amounts of rice and coffee every year.","vi":"Việt Nam xuất khẩu một lượng lớn gạo và cà phê mỗi năm."},{"en":"The factory exports most of its furniture to Europe.","vi":"Nhà máy xuất khẩu phần lớn đồ nội thất sang châu Âu."},{"en":"You can export the file as a PDF before sending it.","vi":"Bạn có thể xuất tệp sang định dạng PDF trước khi gửi đi."}]', '[{"phrase":"export goods"},{"phrase":"export to"},{"phrase":"export data"}]', 'export ≠ import (nhập khẩu)', '/ˈekspɔːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expor/export__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 14, 'entirely', 'hoàn toàn', 'adverb', '[{"en":"I''m not entirely sure what time the meeting starts.","vi":"Tôi không hoàn toàn chắc cuộc họp bắt đầu lúc mấy giờ."},{"en":"The accident was entirely my fault, not the other driver''s.","vi":"Vụ tai nạn hoàn toàn là lỗi của tôi, không phải của người lái xe kia."},{"en":"The house is built almost entirely of wood.","vi":"Ngôi nhà được xây gần như hoàn toàn bằng gỗ."}]', '[{"phrase":"entirely different"},{"phrase":"not entirely sure"},{"phrase":"almost entirely"},{"phrase":"entirely possible"}]', NULL, '/ɪnˈtaɪərli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ent/entir/entirely__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 15, 'strongly', 'mạnh mẽ; kiên quyết; nồng (mùi)', 'adverb', '[{"en":"I strongly recommend booking your tickets as early as possible.","vi":"Tôi thực sự khuyên bạn nên đặt vé càng sớm càng tốt."},{"en":"Many parents feel strongly about the new school rules.","vi":"Nhiều phụ huynh có quan điểm rất mạnh mẽ về nội quy mới của trường."},{"en":"The kitchen smelled strongly of garlic and onions.","vi":"Nhà bếp nồng nặc mùi tỏi và hành."}]', '[{"phrase":"strongly recommend"},{"phrase":"strongly believe"},{"phrase":"feel strongly about"},{"phrase":"strongly disagree"}]', NULL, '/ˈstrɔːŋli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stron/strongly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 16, 'bridge', 'cây cầu; cầu nối', 'noun', '[{"en":"They are building a new bridge across the river.","vi":"Người ta đang xây một cây cầu mới bắc qua sông."},{"en":"We walked over the bridge to the old part of town.","vi":"Chúng tôi đi bộ qua cầu sang khu phố cổ."},{"en":"Music can act as a bridge between different cultures.","vi":"Âm nhạc có thể là cầu nối giữa các nền văn hóa khác nhau."}]', '[{"phrase":"cross the bridge"},{"phrase":"build a bridge"},{"phrase":"bridge over"},{"phrase":"bridge between"}]', NULL, '/brɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bri/bridg/bridge__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 17, 'consist', 'gồm có, bao gồm', 'verb', '[{"en":"The team consists of five designers and two engineers.","vi":"Nhóm gồm có năm nhà thiết kế và hai kỹ sư."},{"en":"Breakfast consisted of bread, eggs and a cup of tea.","vi":"Bữa sáng gồm bánh mì, trứng và một tách trà."},{"en":"The test consists mainly of multiple-choice questions.","vi":"Bài kiểm tra chủ yếu gồm các câu hỏi trắc nghiệm."}]', '[{"phrase":"consist of"},{"phrase":"consist mainly of"},{"phrase":"consist largely of"}]', 'consist of sth; không dùng ở thể bị động hay tiếp diễn', '/kənˈsɪst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsist__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 18, 'graduate', 'tốt nghiệp', 'verb', '[{"en":"My sister graduated from university last summer.","vi":"Chị tôi tốt nghiệp đại học vào mùa hè năm ngoái."},{"en":"After he graduates, he wants to work abroad for a year.","vi":"Sau khi tốt nghiệp, anh ấy muốn ra nước ngoài làm việc một năm."},{"en":"She graduated with a degree in computer science.","vi":"Cô ấy tốt nghiệp với tấm bằng ngành khoa học máy tính."}]', '[{"phrase":"graduate from"},{"phrase":"graduate with a degree"},{"phrase":"graduate from high school"}]', 'graduate from + trường; danh từ: graduate = người đã tốt nghiệp', '/ˈɡrædʒuət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/gradu/graduate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 19, 'brand', 'nhãn hiệu; thương hiệu', 'noun', '[{"en":"Which brand of coffee do you usually buy?","vi":"Bạn thường mua cà phê của hiệu nào?"},{"en":"The company spent millions building its brand in Asia.","vi":"Công ty đã chi hàng triệu đô la để xây dựng thương hiệu ở châu Á."},{"en":"Supermarket brands are often just as good as the famous ones.","vi":"Hàng mang nhãn hiệu của siêu thị thường tốt không kém các hãng nổi tiếng."}]', '[{"phrase":"brand name"},{"phrase":"brand of"},{"phrase":"leading brand"},{"phrase":"brand image"}]', NULL, '/brænd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bra/brand/brand__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 20, 'moral', '(thuộc) đạo đức', 'adjective', '[{"en":"Parents have a moral duty to take care of their children.","vi":"Cha mẹ có trách nhiệm về mặt đạo đức phải chăm sóc con cái."},{"en":"Doctors often face difficult moral questions in their work.","vi":"Các bác sĩ thường phải đối mặt với những câu hỏi khó về đạo đức trong công việc."},{"en":"She has strong moral values and always tells the truth.","vi":"Cô ấy có những giá trị đạo đức vững vàng và luôn nói thật."}]', '[{"phrase":"moral duty"},{"phrase":"moral values"},{"phrase":"moral issue"}]', 'danh từ: the moral = bài học rút ra (từ câu chuyện)', '/ˈmɔːrəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mor/moral/moral__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 21, 'insist', 'nhất quyết; khăng khăng', 'verb', '[{"en":"My mother insisted that I wear a warm coat.","vi":"Mẹ tôi nhất quyết bắt tôi mặc áo khoác ấm."},{"en":"He insists on paying whenever we eat out together.","vi":"Lần nào chúng tôi đi ăn cùng nhau anh ấy cũng nhất quyết đòi trả tiền."},{"en":"She insisted she had never seen the man before.","vi":"Cô ấy khăng khăng rằng mình chưa từng gặp người đàn ông đó."}]', '[{"phrase":"insist on"},{"phrase":"insist that"},{"phrase":"insist on paying"}]', 'insist on + V-ing; insist that + mệnh đề', '/ɪnˈsɪst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insis/insist__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 22, 'combination', 'sự kết hợp; mã số (khóa)', 'noun', '[{"en":"Success usually comes from a combination of talent and hard work.","vi":"Thành công thường đến từ sự kết hợp giữa tài năng và sự chăm chỉ."},{"en":"Red and green is an unusual color combination for a kitchen.","vi":"Đỏ và xanh lá là một sự kết hợp màu lạ cho căn bếp."},{"en":"I forgot the combination to my bike lock.","vi":"Tôi quên mất mã số khóa xe đạp của mình."}]', '[{"phrase":"a combination of"},{"phrase":"in combination with"},{"phrase":"color combination"},{"phrase":"unique combination"}]', NULL, '/ˌkɑːmbɪˈneɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/combi/combination__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 23, 'abuse', 'sự lạm dụng; lời lăng mạ', 'noun', '[{"en":"The new law aims to prevent the abuse of power.","vi":"Luật mới nhằm ngăn chặn tình trạng lạm dụng quyền lực."},{"en":"Alcohol abuse can cause serious health problems.","vi":"Lạm dụng rượu bia có thể gây ra những vấn đề sức khỏe nghiêm trọng."},{"en":"Shop staff should not have to put up with abuse from customers.","vi":"Nhân viên cửa hàng không đáng phải chịu những lời lăng mạ từ khách hàng."}]', '[{"phrase":"abuse of power"},{"phrase":"alcohol abuse"},{"phrase":"verbal abuse"}]', 'động từ: abuse /əˈbjuːz/; danh từ: abuse /əˈbjuːs/', '/əˈbjuːs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abu/abuse/abuse__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 24, 'ice', 'nước đá; băng', 'noun', '[{"en":"Would you like some ice in your drink?","vi":"Bạn có muốn cho thêm đá vào đồ uống không?"},{"en":"Be careful, the roads are covered in ice this morning.","vi":"Cẩn thận nhé, sáng nay đường phủ đầy băng."},{"en":"The children went skating on the ice after school.","vi":"Sau giờ học, bọn trẻ đi trượt trên mặt băng."}]', '[{"phrase":"ice cube"},{"phrase":"thin ice"},{"phrase":"covered in ice"}]', 'không đếm được', '/aɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ice/ice__/ice__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 25, 'principal', 'chính, chủ yếu', 'adjective', '[{"en":"Tourism is the principal source of income for the island.","vi":"Du lịch là nguồn thu nhập chính của hòn đảo."},{"en":"Our principal concern is the safety of the children.","vi":"Mối quan tâm chính của chúng tôi là sự an toàn của bọn trẻ."},{"en":"The principal reason for the delay was bad weather.","vi":"Lý do chính của sự chậm trễ là thời tiết xấu."}]', '[{"phrase":"principal reason"},{"phrase":"principal source"},{"phrase":"principal aim"}]', 'danh từ (Mỹ): hiệu trưởng; principal ≠ principle (nguyên tắc)', '/ˈprɪnsəpl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/princ/principal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 26, 'master', 'thành thạo; nắm vững', 'verb', '[{"en":"It takes years to master a foreign language.","vi":"Phải mất nhiều năm mới thành thạo được một ngoại ngữ."},{"en":"Once you master the basic steps, the dance is easy.","vi":"Một khi đã nắm vững các bước cơ bản thì điệu nhảy này dễ thôi."},{"en":"She mastered the guitar in less than two years.","vi":"Cô ấy chơi thành thạo đàn guitar chỉ trong chưa đầy hai năm."}]', '[{"phrase":"master a skill"},{"phrase":"master a language"},{"phrase":"master the basics"}]', 'danh từ: master = bậc thầy; chủ nhân', '/ˈmæstər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mas/maste/master__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 27, 'definitely', 'chắc chắn; nhất định', 'adverb', '[{"en":"I''ll definitely call you when I get home.","vi":"Về đến nhà tôi nhất định sẽ gọi cho bạn."},{"en":"This is definitely the best pizza I''ve ever had.","vi":"Đây chắc chắn là chiếc pizza ngon nhất tôi từng ăn."},{"en":"We''re definitely going to need a bigger car next year.","vi":"Năm sau chắc chắn chúng tôi sẽ cần một chiếc xe lớn hơn."}]', '[{"phrase":"definitely not"},{"phrase":"most definitely"},{"phrase":"definitely worth"}]', NULL, '/ˈdefɪnətli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/def/defin/definitely__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 28, 'session', 'buổi (học, tập); phiên (họp)', 'noun', '[{"en":"I have a training session at the gym every Tuesday.","vi":"Tôi có một buổi tập ở phòng gym vào mỗi thứ Ba."},{"en":"The first session of the conference starts at nine.","vi":"Phiên họp đầu tiên của hội nghị bắt đầu lúc chín giờ."},{"en":"After each session, the teacher gives us some homework.","vi":"Sau mỗi buổi học, giáo viên giao cho chúng tôi một ít bài tập về nhà."}]', '[{"phrase":"training session"},{"phrase":"practice session"},{"phrase":"question-and-answer session"}]', NULL, '/ˈseʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ses/sessi/session__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 29, 'grade', 'điểm (số); lớp (ở trường); loại, hạng', 'noun', '[{"en":"She got good grades in math and science this year.","vi":"Năm nay cô ấy được điểm cao môn toán và khoa học."},{"en":"My son is in the fourth grade at a local school.","vi":"Con trai tôi đang học lớp bốn ở một trường gần nhà."},{"en":"Eggs are sorted into different grades according to their size.","vi":"Trứng được phân thành các loại khác nhau theo kích cỡ."}]', '[{"phrase":"good grades"},{"phrase":"get a grade"},{"phrase":"high grade"}]', NULL, '/ɡreɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/grade/grade__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-02', 30, 'nevertheless', 'tuy nhiên; dù vậy', 'adverb', '[{"en":"The weather was terrible; nevertheless, we enjoyed our trip.","vi":"Thời tiết rất tệ, tuy nhiên chúng tôi vẫn rất thích chuyến đi."},{"en":"It was a hard decision, but nevertheless the right one.","vi":"Đó là một quyết định khó khăn, nhưng dù vậy vẫn là quyết định đúng đắn."},{"en":"He knew the risks but decided to go ahead nevertheless.","vi":"Anh ấy biết rõ rủi ro nhưng dù vậy vẫn quyết định làm tiếp."}]', '[{"phrase":"but nevertheless"},{"phrase":"nevertheless true"},{"phrase":"nevertheless important"}]', NULL, '/ˌnevərðəˈles/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nev/never/nevertheless__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-4-03', 'ngsl-4', 'Thông dụng 1.501–2.000 · Bộ 3', 'New General Service List, thứ hạng 1.501–2.000', '#3da9fc', 'BookOpen', 3);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 1, 'predict', 'dự đoán', 'verb', '[{"en":"Nobody can predict exactly what the weather will do next week.","vi":"Không ai có thể dự đoán chính xác thời tiết tuần sau sẽ thế nào."},{"en":"Experts predict that house prices will rise again this year.","vi":"Các chuyên gia dự đoán giá nhà sẽ lại tăng trong năm nay."},{"en":"The ending of the movie was easy to predict.","vi":"Cái kết của bộ phim rất dễ đoán."}]', '[{"phrase":"predict the future"},{"phrase":"accurately predict"},{"phrase":"difficult to predict"}]', NULL, '/prɪˈdɪkt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/predi/predict__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 2, 'previously', 'trước đây; trước đó', 'adverb', '[{"en":"I had previously worked as a teacher in a small town.","vi":"Trước đây tôi từng làm giáo viên ở một thị trấn nhỏ."},{"en":"The shop was previously a bakery, but now it sells clothes.","vi":"Cửa hàng này trước đây là tiệm bánh, nhưng giờ bán quần áo."},{"en":"As I mentioned previously, the meeting starts at nine.","vi":"Như tôi đã nói trước đó, cuộc họp bắt đầu lúc chín giờ."}]', '[{"phrase":"previously mentioned"},{"phrase":"as previously stated"},{"phrase":"previously unknown"}]', NULL, '/ˈpriːviəsli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/previ/previously__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 3, 'protection', 'sự bảo vệ', 'noun', '[{"en":"Wear sunglasses for protection against the strong summer sun.","vi":"Hãy đeo kính râm để bảo vệ mắt khỏi nắng hè gay gắt."},{"en":"These gloves offer good protection from the cold.","vi":"Đôi găng tay này giúp bảo vệ tốt khỏi cái lạnh."},{"en":"The new law gives better protection to workers.","vi":"Luật mới bảo vệ người lao động tốt hơn."}]', '[{"phrase":"protection against"},{"phrase":"protection from"},{"phrase":"provide protection"},{"phrase":"environmental protection"}]', 'protection against/from sth', '/prəˈtekʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prote/protection__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 4, 'largely', 'phần lớn; chủ yếu', 'adverb', '[{"en":"The success of the town is largely due to tourism.","vi":"Sự thành công của thị trấn chủ yếu là nhờ du lịch."},{"en":"These days her work is largely done from home.","vi":"Dạo này công việc của cô ấy phần lớn được làm ở nhà."},{"en":"My advice was largely ignored by the rest of the team.","vi":"Lời khuyên của tôi phần lớn bị những người còn lại trong nhóm phớt lờ."}]', '[{"phrase":"largely due to"},{"phrase":"largely because"},{"phrase":"largely ignored"}]', NULL, '/ˈlɑːrdʒli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lar/large/largely__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 5, 'wed', 'kết hôn; cưới', 'verb', '[{"en":"They wed in a small garden ceremony last spring.","vi":"Họ kết hôn trong một buổi lễ nhỏ ngoài vườn vào mùa xuân năm ngoái."},{"en":"My sister and her boyfriend plan to get wed next year.","vi":"Chị tôi và bạn trai dự định cưới nhau vào năm sau."},{"en":"The couple were wed on a beach near their hometown.","vi":"Cặp đôi đã cưới nhau trên một bãi biển gần quê nhà."}]', '[{"phrase":"get wed"},{"phrase":"newly wed"}]', 'wed – wed/wedded – wed/wedded; hay dùng trong báo chí', '/wed/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wed/wed__/wed__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 6, 'rent', 'thuê; cho thuê', 'verb', '[{"en":"We rented a small car for our trip to the coast.","vi":"Chúng tôi đã thuê một chiếc xe nhỏ cho chuyến đi biển."},{"en":"They rent a two-bedroom apartment near the city center.","vi":"Họ thuê một căn hộ hai phòng ngủ gần trung tâm thành phố."},{"en":"My uncle rents his old house to students.","vi":"Chú tôi cho sinh viên thuê căn nhà cũ của chú."}]', '[{"phrase":"rent an apartment"},{"phrase":"rent a car"},{"phrase":"rent out"}]', 'danh từ: tiền thuê (pay the rent)', '/rent/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ren/rent_/rent__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 7, 'shot', 'cú sút; bức ảnh; mũi tiêm', 'noun', '[{"en":"His shot hit the post in the last minute of the game.","vi":"Cú sút của anh ấy trúng cột dọc ở phút cuối trận."},{"en":"She took a beautiful shot of the sunset from the balcony.","vi":"Cô ấy chụp được một bức ảnh hoàng hôn rất đẹp từ ban công."},{"en":"The nurse said the flu shot would not hurt much.","vi":"Y tá nói mũi tiêm phòng cúm sẽ không đau lắm."}]', '[{"phrase":"take a shot"},{"phrase":"flu shot"},{"phrase":"good shot"}]', NULL, '/ʃɑːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/shot_/shot__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 8, 'appearance', 'vẻ bề ngoài; sự xuất hiện', 'noun', '[{"en":"He cares a lot about his appearance.","vi":"Anh ấy rất quan tâm đến vẻ bề ngoài của mình."},{"en":"She changed her appearance completely by cutting her hair short.","vi":"Cô ấy thay đổi hoàn toàn vẻ ngoài bằng cách cắt tóc ngắn."},{"en":"The singer made a short appearance at the end of the show.","vi":"Ca sĩ xuất hiện chớp nhoáng vào cuối chương trình."}]', '[{"phrase":"physical appearance"},{"phrase":"make an appearance"},{"phrase":"sudden appearance"}]', NULL, '/əˈpɪrəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appea/appearance__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 9, 'reasonable', 'hợp lý; phải chăng', 'adjective', '[{"en":"The hotel was clean and the prices were very reasonable.","vi":"Khách sạn sạch sẽ và giá cả rất phải chăng."},{"en":"That sounds like a reasonable plan to me.","vi":"Tôi thấy đó có vẻ là một kế hoạch hợp lý."},{"en":"We need a reasonable amount of time to finish the job.","vi":"Chúng tôi cần một khoảng thời gian hợp lý để hoàn thành công việc."}]', '[{"phrase":"reasonable price"},{"phrase":"reasonable explanation"},{"phrase":"perfectly reasonable"}]', NULL, '/ˈriːznəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/reaso/reasonable__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 10, 'guarantee', 'đảm bảo; cam kết', 'verb', '[{"en":"Hard work does not guarantee success, but it certainly helps.","vi":"Làm việc chăm chỉ không đảm bảo thành công, nhưng chắc chắn là có ích."},{"en":"We guarantee delivery within three working days.","vi":"Chúng tôi cam kết giao hàng trong vòng ba ngày làm việc."},{"en":"I cannot guarantee that the train will be on time.","vi":"Tôi không thể đảm bảo tàu sẽ đến đúng giờ."}]', '[{"phrase":"guarantee success"},{"phrase":"cannot guarantee"},{"phrase":"money-back guarantee"}]', 'danh từ: sự bảo đảm; giấy bảo hành', '/ˌɡærənˈtiː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gua/guara/guarantee__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 11, 'till', 'cho đến; đến tận', 'preposition', '[{"en":"I worked till midnight to finish my report.","vi":"Tôi làm việc đến tận nửa đêm để hoàn thành báo cáo."},{"en":"We stayed at the beach till sunset.","vi":"Chúng tôi ở lại bãi biển cho đến lúc hoàng hôn."},{"en":"The store is open till ten o''clock tonight.","vi":"Cửa hàng mở cửa đến mười giờ tối nay."}]', '[{"phrase":"till now"},{"phrase":"till then"},{"phrase":"from morning till night"}]', 'thân mật, nghĩa như until', '/tɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/til/till_/till__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 12, 'theme', 'chủ đề', 'noun', '[{"en":"The main theme of the book is friendship.","vi":"Chủ đề chính của cuốn sách là tình bạn."},{"en":"Love and loss are common themes in her songs.","vi":"Tình yêu và mất mát là những chủ đề thường gặp trong các bài hát của cô ấy."},{"en":"Our party had a movie theme, so everyone dressed up.","vi":"Bữa tiệc của chúng tôi có chủ đề phim ảnh, nên ai cũng hóa trang."}]', '[{"phrase":"main theme"},{"phrase":"common theme"},{"phrase":"central theme"},{"phrase":"theme park"}]', NULL, '/θiːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/theme/theme__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 13, 'judgment', 'sự phán đoán; óc suy xét', 'noun', '[{"en":"I trust your judgment on this matter.","vi":"Tôi tin vào sự phán đoán của bạn trong chuyện này."},{"en":"Try not to make quick judgments about people you have just met.","vi":"Cố đừng vội đánh giá những người bạn mới gặp."},{"en":"Being very tired can affect your judgment when you drive.","vi":"Quá mệt có thể ảnh hưởng đến khả năng phán đoán khi bạn lái xe."}]', '[{"phrase":"good judgment"},{"phrase":"poor judgment"},{"phrase":"make a judgment"},{"phrase":"trust your judgment"}]', 'Mỹ: judgment · Anh: judgement', '/ˈdʒʌdʒmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 14, 'odd', 'kỳ lạ; lẻ', 'adjective', '[{"en":"It is odd that he has not called me back yet.","vi":"Thật lạ là anh ấy vẫn chưa gọi lại cho tôi."},{"en":"My new neighbor seems a bit odd, but he is friendly.","vi":"Người hàng xóm mới của tôi có vẻ hơi kỳ lạ, nhưng anh ấy thân thiện."},{"en":"Three, five and seven are all odd numbers.","vi":"Ba, năm và bảy đều là số lẻ."}]', '[{"phrase":"odd number"},{"phrase":"a bit odd"},{"phrase":"seem odd"}]', NULL, '/ɑːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/odd/odd__/odd__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 15, 'approve', 'chấp thuận; tán thành', 'verb', '[{"en":"The manager approved my request for a week off.","vi":"Quản lý đã chấp thuận đơn xin nghỉ một tuần của tôi."},{"en":"My parents did not approve of my decision to quit my job.","vi":"Bố mẹ tôi không tán thành quyết định nghỉ việc của tôi."},{"en":"The city has approved plans for a new park.","vi":"Thành phố đã chấp thuận kế hoạch xây một công viên mới."}]', '[{"phrase":"approve of"},{"phrase":"approve a plan"},{"phrase":"approve a request"}]', 'approve of sth: tán thành điều gì', '/əˈpruːv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appro/approve__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 16, 'loan', 'khoản vay; sự cho vay', 'noun', '[{"en":"She took out a loan to buy her first car.","vi":"Cô ấy đã vay tiền để mua chiếc ô tô đầu tiên."},{"en":"The bank refused to give him a loan.","vi":"Ngân hàng từ chối cho anh ấy vay tiền."},{"en":"It will take us ten years to pay back the loan.","vi":"Chúng tôi sẽ mất mười năm để trả hết khoản vay."}]', '[{"phrase":"take out a loan"},{"phrase":"bank loan"},{"phrase":"student loan"},{"phrase":"pay back a loan"}]', NULL, '/ləʊn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/loa/loan_/loan__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 17, 'definition', 'định nghĩa', 'noun', '[{"en":"Look up the definition of this word in your dictionary.","vi":"Hãy tra định nghĩa của từ này trong từ điển của bạn."},{"en":"Everyone has their own definition of success.","vi":"Mỗi người có một định nghĩa riêng về thành công."},{"en":"Can you give me a clear definition of the term?","vi":"Bạn có thể cho tôi một định nghĩa rõ ràng về thuật ngữ này không?"}]', '[{"phrase":"clear definition"},{"phrase":"by definition"},{"phrase":"dictionary definition"}]', NULL, '/ˌdefɪˈnɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/def/defin/definition__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 18, 'elect', 'bầu; bầu chọn', 'verb', '[{"en":"The students elected a new class president this morning.","vi":"Sáng nay học sinh đã bầu lớp trưởng mới."},{"en":"Club members elect a new chairman every year.","vi":"Các thành viên câu lạc bộ bầu chủ tịch mới mỗi năm."},{"en":"He was elected captain of the football team.","vi":"Anh ấy được bầu làm đội trưởng đội bóng đá."}]', '[{"phrase":"be elected"},{"phrase":"newly elected"},{"phrase":"elect a leader"}]', NULL, '/ɪˈlekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ele/elect/elect__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 19, 'atmosphere', 'bầu không khí; khí quyển', 'noun', '[{"en":"The restaurant has a warm and friendly atmosphere.","vi":"Nhà hàng có bầu không khí ấm cúng và thân thiện."},{"en":"There was a tense atmosphere in the office after the meeting.","vi":"Không khí trong văn phòng rất căng thẳng sau cuộc họp."},{"en":"Cars release harmful gases into the atmosphere every day.","vi":"Ô tô thải khí độc hại vào khí quyển mỗi ngày."}]', '[{"phrase":"friendly atmosphere"},{"phrase":"relaxed atmosphere"},{"phrase":"the earth''s atmosphere"}]', NULL, '/ˈætməsfɪr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/atm/atmos/atmosphere__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 20, 'farmer', 'nông dân', 'noun', '[{"en":"The farmer gets up at five to feed his cows.","vi":"Người nông dân dậy lúc năm giờ để cho bò ăn."},{"en":"Many farmers grow rice and vegetables in this area.","vi":"Nhiều nông dân trồng lúa và rau ở vùng này."},{"en":"We buy fresh eggs from a local farmer every week.","vi":"Chúng tôi mua trứng tươi của một bác nông dân địa phương mỗi tuần."}]', '[{"phrase":"local farmer"},{"phrase":"rice farmer"},{"phrase":"dairy farmer"}]', NULL, '/ˈfɑːrmər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/far/farme/farmer__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 21, 'comparison', 'sự so sánh', 'noun', '[{"en":"Sales this year are low in comparison with last year.","vi":"Doanh số năm nay thấp so với năm ngoái."},{"en":"It is hard to make a comparison between the two cities.","vi":"Thật khó để so sánh hai thành phố này."},{"en":"My new laptop is fast, and my old one seems slow by comparison.","vi":"Máy tính mới của tôi rất nhanh, so ra thì máy cũ có vẻ chậm."}]', '[{"phrase":"in comparison with"},{"phrase":"make a comparison"},{"phrase":"by comparison"}]', NULL, '/kəmˈpærɪsn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compa/comparison__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 22, 'characteristic', 'đặc điểm; đặc trưng', 'noun', '[{"en":"Patience is an important characteristic of a good teacher.","vi":"Kiên nhẫn là một đặc điểm quan trọng của một giáo viên giỏi."},{"en":"The two cats share many physical characteristics.","vi":"Hai con mèo có nhiều đặc điểm ngoại hình giống nhau."},{"en":"What are the main characteristics of this style of painting?","vi":"Những đặc trưng chính của phong cách hội họa này là gì?"}]', '[{"phrase":"physical characteristics"},{"phrase":"main characteristic"},{"phrase":"common characteristic"}]', 'cũng là tính từ: đặc trưng, tiêu biểu', '/ˌkærəktəˈrɪstɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chara/characteristic__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 23, 'license', 'giấy phép; bằng lái', 'noun', '[{"en":"You need a license to open a restaurant here.","vi":"Bạn cần có giấy phép để mở nhà hàng ở đây."},{"en":"He finally got his driver''s license at the age of twenty.","vi":"Cuối cùng anh ấy cũng lấy được bằng lái xe năm hai mươi tuổi."},{"en":"The police officer asked to see my license.","vi":"Viên cảnh sát yêu cầu xem bằng lái của tôi."}]', '[{"phrase":"driver''s license"},{"phrase":"get a license"},{"phrase":"business license"}]', 'Mỹ: license · Anh: licence (danh từ)', '/ˈlaɪsns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lic/licen/license__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 24, 'rely', 'dựa vào; tin cậy', 'verb', '[{"en":"Many students rely on their parents for money.","vi":"Nhiều sinh viên dựa vào bố mẹ về tiền bạc."},{"en":"You can always rely on her to tell the truth.","vi":"Bạn luôn có thể tin cô ấy sẽ nói thật."},{"en":"We should not rely too much on our phones.","vi":"Chúng ta không nên dựa dẫm quá nhiều vào điện thoại."}]', '[{"phrase":"rely on"},{"phrase":"rely heavily on"},{"phrase":"can rely on"}]', 'rely on/upon sb/sth', '/rɪˈlaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/rely_/rely__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 25, 'narrow', 'hẹp; sít sao', 'adjective', '[{"en":"The streets in the old town are very narrow.","vi":"Đường phố ở khu phố cổ rất hẹp."},{"en":"We walked along a narrow path by the river.","vi":"Chúng tôi đi bộ dọc theo một con đường hẹp bên sông."},{"en":"Our team won a narrow victory in the final game.","vi":"Đội chúng tôi giành chiến thắng sít sao trong trận cuối cùng."}]', '[{"phrase":"narrow street"},{"phrase":"narrow path"},{"phrase":"narrow victory"},{"phrase":"narrow escape"}]', NULL, '/ˈnærəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nar/narro/narrow__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 26, 'succeed', 'thành công', 'verb', '[{"en":"If you keep working hard, you will succeed.","vi":"Nếu bạn tiếp tục chăm chỉ, bạn sẽ thành công."},{"en":"She succeeded in passing the exam on her first try.","vi":"Cô ấy đã thành công vượt qua kỳ thi ngay lần đầu."},{"en":"After many months, our plan to save money finally succeeded.","vi":"Sau nhiều tháng, kế hoạch tiết kiệm tiền của chúng tôi cuối cùng đã thành công."}]', '[{"phrase":"succeed in"},{"phrase":"finally succeed"},{"phrase":"succeed in business"}]', 'succeed in doing sth', '/səkˈsiːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/suc/succe/succeed__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 27, 'identity', 'danh tính; bản sắc', 'noun', '[{"en":"Please bring a document that proves your identity.","vi":"Vui lòng mang theo giấy tờ chứng minh danh tính của bạn."},{"en":"The identity of the winner will be announced tomorrow.","vi":"Danh tính người chiến thắng sẽ được công bố vào ngày mai."},{"en":"Language is an important part of a country''s cultural identity.","vi":"Ngôn ngữ là một phần quan trọng trong bản sắc văn hóa của một quốc gia."}]', '[{"phrase":"identity card"},{"phrase":"cultural identity"},{"phrase":"national identity"},{"phrase":"prove your identity"}]', NULL, '/aɪˈdentəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ide/ident/identity__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 28, 'desk', 'bàn làm việc; bàn học; quầy', 'noun', '[{"en":"I keep a small plant on my desk at work.","vi":"Tôi để một chậu cây nhỏ trên bàn làm việc ở công ty."},{"en":"Please leave your key at the front desk.","vi":"Vui lòng để lại chìa khóa ở quầy lễ tân."},{"en":"The kids did their homework at the desk in their room.","vi":"Bọn trẻ làm bài tập ở bàn học trong phòng."}]', '[{"phrase":"front desk"},{"phrase":"office desk"},{"phrase":"desk job"},{"phrase":"sit at a desk"}]', NULL, '/desk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/desk_/desk__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 29, 'permit', 'cho phép', 'verb', '[{"en":"Smoking is not permitted inside the building.","vi":"Không được phép hút thuốc bên trong tòa nhà."},{"en":"The library rules permit each student to borrow five books.","vi":"Nội quy thư viện cho phép mỗi học sinh mượn năm cuốn sách."},{"en":"We will have a picnic tomorrow, weather permitting.","vi":"Nếu thời tiết cho phép, ngày mai chúng tôi sẽ đi dã ngoại."}]', '[{"phrase":"weather permitting"},{"phrase":"be permitted to"},{"phrase":"permit someone to"}]', 'permit – permitted – permitted; danh từ: giấy phép', '/pərˈmɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/permi/permit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-03', 30, 'seriously', 'nghiêm túc; nghiêm trọng', 'adverb', '[{"en":"You should take your health more seriously.","vi":"Bạn nên coi trọng sức khỏe của mình hơn."},{"en":"The old house was seriously damaged by the storm.","vi":"Ngôi nhà cũ bị cơn bão làm hư hại nghiêm trọng."},{"en":"Are you seriously thinking about moving abroad?","vi":"Bạn đang nghiêm túc tính chuyện ra nước ngoài sống à?"}]', '[{"phrase":"take seriously"},{"phrase":"seriously damaged"},{"phrase":"seriously consider"}]', NULL, '/ˈsɪriəsli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ser/serio/seriously__us_2.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-4-04', 'ngsl-4', 'Thông dụng 1.501–2.000 · Bộ 4', 'New General Service List, thứ hạng 1.501–2.000', '#3da9fc', 'BookOpen', 4);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 1, 'wild', 'hoang dã; cuồng nhiệt, điên cuồng', 'adjective', '[{"en":"We saw wild elephants during our trip to the national park.","vi":"Chúng tôi đã thấy voi hoang dã trong chuyến đi đến vườn quốc gia."},{"en":"These wild flowers grow everywhere along the river in spring.","vi":"Những bông hoa dại này mọc khắp nơi dọc bờ sông vào mùa xuân."},{"en":"The crowd went wild when the band came on stage.","vi":"Đám đông trở nên cuồng nhiệt khi ban nhạc bước lên sân khấu."}]', '[{"phrase":"wild animals"},{"phrase":"wild flowers"},{"phrase":"go wild"},{"phrase":"wild guess"}]', NULL, '/waɪld/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wil/wild_/wild__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 2, 'empty', 'trống, rỗng; vắng vẻ', 'adjective', '[{"en":"Please put the empty bottles in the recycling bin.","vi":"Vui lòng bỏ những chai rỗng vào thùng tái chế."},{"en":"The streets were completely empty early on Sunday morning.","vi":"Đường phố hoàn toàn vắng vẻ vào sáng sớm Chủ nhật."},{"en":"Is this seat empty, or is someone sitting here?","vi":"Ghế này còn trống không, hay đã có người ngồi rồi?"}]', '[{"phrase":"empty bottle"},{"phrase":"empty room"},{"phrase":"completely empty"},{"phrase":"empty seat"}]', NULL, '/ˈempti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emp/empty/empty__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 3, 'commission', 'ủy ban; tiền hoa hồng', 'noun', '[{"en":"The government set up a commission to study the problem.","vi":"Chính phủ đã thành lập một ủy ban để nghiên cứu vấn đề này."},{"en":"She earns a commission on every house she sells.","vi":"Cô ấy nhận tiền hoa hồng cho mỗi căn nhà cô ấy bán được."},{"en":"Salespeople in this shop are paid mostly on commission.","vi":"Nhân viên bán hàng ở cửa hàng này chủ yếu được trả lương theo hoa hồng."}]', '[{"phrase":"set up a commission"},{"phrase":"earn a commission"},{"phrase":"on commission"}]', 'on commission: hưởng theo hoa hồng', '/kəˈmɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commi/commission__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 4, 'unique', 'độc nhất, duy nhất; độc đáo', 'adjective', '[{"en":"Every person has a unique set of fingerprints.","vi":"Mỗi người đều có một bộ dấu vân tay độc nhất."},{"en":"This small town has a unique style of cooking.","vi":"Thị trấn nhỏ này có một phong cách nấu ăn độc đáo."},{"en":"This problem is not unique to our school.","vi":"Vấn đề này không chỉ riêng trường chúng ta mới có."}]', '[{"phrase":"unique opportunity"},{"phrase":"unique to"},{"phrase":"truly unique"},{"phrase":"unique style"}]', 'unique to sth: chỉ riêng có ở', '/juˈniːk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/uniqu/unique__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 5, 'association', 'hiệp hội; mối liên hệ, sự liên kết', 'noun', '[{"en":"My father is a member of the local football association.","vi":"Bố tôi là thành viên của hiệp hội bóng đá địa phương."},{"en":"The teachers formed an association to protect their rights.","vi":"Các giáo viên đã thành lập một hiệp hội để bảo vệ quyền lợi của mình."},{"en":"Scientists found a strong association between smoking and heart disease.","vi":"Các nhà khoa học tìm thấy mối liên hệ chặt chẽ giữa hút thuốc và bệnh tim."}]', '[{"phrase":"in association with"},{"phrase":"association between"},{"phrase":"form an association"},{"phrase":"strong association"}]', NULL, '/əˌsəʊsiˈeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assoc/association__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 6, 'instrument', 'nhạc cụ; dụng cụ', 'noun', '[{"en":"Can you play any musical instruments, like the guitar?","vi":"Bạn có chơi được nhạc cụ nào không, chẳng hạn như đàn guitar?"},{"en":"The piano was the first instrument she learned to play.","vi":"Đàn piano là nhạc cụ đầu tiên cô ấy học chơi."},{"en":"The nurse cleaned all the instruments before the operation.","vi":"Y tá đã làm sạch tất cả dụng cụ trước ca mổ."}]', '[{"phrase":"musical instrument"},{"phrase":"play an instrument"},{"phrase":"medical instruments"}]', NULL, '/ˈɪnstrəmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/instr/instrument__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 7, 'investor', 'nhà đầu tư', 'noun', '[{"en":"The company is looking for investors to help it grow.","vi":"Công ty đang tìm kiếm nhà đầu tư để giúp mình phát triển."},{"en":"Many small investors lost money when prices fell.","vi":"Nhiều nhà đầu tư nhỏ lẻ đã mất tiền khi giá giảm."},{"en":"Foreign investors are showing more interest in the city.","vi":"Các nhà đầu tư nước ngoài đang quan tâm nhiều hơn đến thành phố này."}]', '[{"phrase":"foreign investors"},{"phrase":"small investors"},{"phrase":"attract investors"},{"phrase":"private investor"}]', NULL, '/ɪnˈvestər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/inves/investor__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 8, 'practical', 'thực tế; thiết thực, tiện dụng', 'adjective', '[{"en":"The course gives students practical experience in real companies.","vi":"Khóa học mang lại cho sinh viên kinh nghiệm thực tế tại các công ty thật."},{"en":"These shoes are not very pretty, but they are practical.","vi":"Đôi giày này không đẹp lắm, nhưng rất tiện dụng."},{"en":"We need a practical solution, not just good ideas.","vi":"Chúng ta cần một giải pháp thiết thực, chứ không chỉ là ý tưởng hay."}]', '[{"phrase":"practical experience"},{"phrase":"practical solution"},{"phrase":"practical advice"},{"phrase":"practical skills"}]', NULL, '/ˈpræktɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pra/pract/practical__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 9, 'tea', 'trà', 'noun', '[{"en":"Would you like a cup of tea?","vi":"Bạn có muốn một tách trà không?"},{"en":"My grandmother drinks green tea every morning after breakfast.","vi":"Bà tôi uống trà xanh mỗi sáng sau bữa sáng."},{"en":"I made some tea while we waited for the rain to stop.","vi":"Tôi pha một ít trà trong lúc chúng tôi chờ mưa tạnh."}]', '[{"phrase":"cup of tea"},{"phrase":"green tea"},{"phrase":"make tea"},{"phrase":"drink tea"}]', NULL, '/tiː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tea/tea__/tea__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 10, 'lovely', 'đẹp, đáng yêu; rất dễ chịu, tuyệt', 'adjective', '[{"en":"You have a lovely garden with so many flowers.","vi":"Bạn có một khu vườn thật đẹp với rất nhiều hoa."},{"en":"We had a lovely time at the beach last weekend.","vi":"Cuối tuần trước chúng tôi đã có khoảng thời gian thật tuyệt ở bãi biển."},{"en":"It would be lovely to see you again soon.","vi":"Thật tuyệt nếu sớm được gặp lại bạn."}]', '[{"phrase":"lovely day"},{"phrase":"have a lovely time"},{"phrase":"lovely to see you"},{"phrase":"absolutely lovely"}]', NULL, '/ˈlʌvli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lov/lovel/lovely__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 11, 'soft', 'mềm; nhẹ nhàng, dịu', 'adjective', '[{"en":"This pillow is too soft for me.","vi":"Cái gối này quá mềm đối với tôi."},{"en":"The baby has soft skin and tiny fingers.","vi":"Em bé có làn da mềm mại và những ngón tay nhỏ xíu."},{"en":"She spoke in a soft voice so she would not wake anyone.","vi":"Cô ấy nói bằng giọng nhẹ nhàng để không đánh thức ai."}]', '[{"phrase":"soft voice"},{"phrase":"soft music"},{"phrase":"soft drink"},{"phrase":"soft skin"}]', NULL, '/sɔːft/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sof/soft_/soft__us_5.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 12, 'row', 'hàng, dãy', 'noun', '[{"en":"We sat in the front row at the concert.","vi":"Chúng tôi ngồi ở hàng ghế đầu trong buổi hòa nhạc."},{"en":"There is a row of small shops along this street.","vi":"Có một dãy cửa hàng nhỏ dọc con phố này."},{"en":"Our team has won five games in a row.","vi":"Đội chúng tôi đã thắng năm trận liên tiếp."}]', '[{"phrase":"front row"},{"phrase":"in a row"},{"phrase":"row of houses"},{"phrase":"back row"}]', 'in a row: liên tiếp', '/ˈroʊ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 13, 'youth', 'tuổi trẻ; thanh thiếu niên', 'noun', '[{"en":"He spent most of his youth in a small village.","vi":"Anh ấy đã trải qua phần lớn tuổi trẻ ở một ngôi làng nhỏ."},{"en":"In her youth, she was a very fast runner.","vi":"Thời trẻ, cô ấy chạy rất nhanh."},{"en":"The city opened a new youth center for local teenagers.","vi":"Thành phố đã mở một trung tâm thanh thiếu niên mới cho các bạn trẻ địa phương."}]', '[{"phrase":"in your youth"},{"phrase":"youth club"},{"phrase":"youth center"}]', NULL, '/juːθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/y/you/youth/youth__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 14, 'lock', 'khóa', 'verb', '[{"en":"Did you lock the front door before we left?","vi":"Bạn đã khóa cửa trước trước khi chúng ta đi chưa?"},{"en":"Always lock your bike when you leave it outside.","vi":"Luôn khóa xe đạp khi bạn để nó ở bên ngoài."},{"en":"The office is locked at night, so nobody can get in.","vi":"Văn phòng được khóa vào ban đêm nên không ai vào được."}]', '[{"phrase":"lock the door"},{"phrase":"lock up"},{"phrase":"keep something locked"}]', NULL, '/lɑːk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/loc/lock_/lock__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 15, 'fuel', 'nhiên liệu', 'noun', '[{"en":"The price of fuel has gone up again this month.","vi":"Giá nhiên liệu lại tăng trong tháng này."},{"en":"Our car ran out of fuel on the way home.","vi":"Xe của chúng tôi hết nhiên liệu trên đường về nhà."},{"en":"Bigger cars usually use more fuel than small ones.","vi":"Xe lớn thường tốn nhiều nhiên liệu hơn xe nhỏ."}]', '[{"phrase":"fuel prices"},{"phrase":"run out of fuel"},{"phrase":"use fuel"},{"phrase":"fossil fuels"}]', NULL, '/ˈfjuːəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fue/fuel_/fuel__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 16, 'expectation', 'sự mong đợi, kỳ vọng', 'noun', '[{"en":"Her parents have very high expectations for her.","vi":"Bố mẹ cô ấy đặt kỳ vọng rất cao vào cô ấy."},{"en":"The hotel was much better than our expectations.","vi":"Khách sạn tốt hơn nhiều so với mong đợi của chúng tôi."},{"en":"The new phone did not meet customers’ expectations.","vi":"Chiếc điện thoại mới đã không đáp ứng được kỳ vọng của khách hàng."}]', '[{"phrase":"high expectations"},{"phrase":"meet expectations"},{"phrase":"beyond expectations"},{"phrase":"live up to expectations"}]', NULL, '/ˌekspekˈteɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expec/expectation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 17, 'employment', 'việc làm; sự tuyển dụng', 'noun', '[{"en":"Many young people move to cities to find employment.","vi":"Nhiều người trẻ chuyển lên thành phố để tìm việc làm."},{"en":"The new factory will create employment for hundreds of workers.","vi":"Nhà máy mới sẽ tạo việc làm cho hàng trăm công nhân."},{"en":"Please read your employment contract carefully before signing it.","vi":"Vui lòng đọc kỹ hợp đồng lao động trước khi ký."}]', '[{"phrase":"find employment"},{"phrase":"employment contract"},{"phrase":"full-time employment"},{"phrase":"create employment"}]', 'không đếm được', '/ɪmˈplɔɪmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emp/emplo/employment__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 18, 'celebrate', 'ăn mừng; kỷ niệm', 'verb', '[{"en":"We went out for dinner to celebrate her new job.","vi":"Chúng tôi đi ăn tối để ăn mừng việc cô ấy có công việc mới."},{"en":"My parents are celebrating their 30th wedding anniversary this year.","vi":"Năm nay bố mẹ tôi kỷ niệm 30 năm ngày cưới."},{"en":"How do people in your country celebrate the New Year?","vi":"Người dân ở nước bạn ăn mừng năm mới như thế nào?"}]', '[{"phrase":"celebrate a birthday"},{"phrase":"celebrate an anniversary"},{"phrase":"celebrate success"}]', NULL, '/ˈselɪbreɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cel/celeb/celebrate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 19, 'sexual', '(thuộc) tình dục; (thuộc) giới tính', 'adjective', '[{"en":"The clinic gives young people free advice about sexual health.","vi":"Phòng khám tư vấn miễn phí cho người trẻ về sức khỏe tình dục."},{"en":"The company has clear rules against sexual harassment at work.","vi":"Công ty có quy định rõ ràng chống quấy rối tình dục nơi làm việc."},{"en":"In biology class, we learned how sexual reproduction works in plants.","vi":"Trong giờ sinh học, chúng tôi đã học về cách sinh sản hữu tính diễn ra ở thực vật."}]', '[{"phrase":"sexual health"},{"phrase":"sexual harassment"},{"phrase":"sexual reproduction"}]', NULL, '/ˈsekʃuəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sex/sexua/sexual__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 20, 'shoulder', 'vai', 'noun', '[{"en":"She put her hand on my shoulder and smiled.","vi":"Cô ấy đặt tay lên vai tôi và mỉm cười."},{"en":"My shoulders hurt after carrying that heavy bag all day.","vi":"Vai tôi đau sau khi mang cái túi nặng đó cả ngày."},{"en":"He looked over his shoulder to see who was there.","vi":"Anh ấy ngoái lại phía sau để xem ai ở đó."}]', '[{"phrase":"over your shoulder"},{"phrase":"shoulder pain"},{"phrase":"shrug your shoulders"}]', NULL, '/ˈʃəʊldər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/shoul/shoulder__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 21, 'breath', 'hơi thở', 'noun', '[{"en":"Take a deep breath and try to relax.","vi":"Hãy hít một hơi thật sâu và cố gắng thư giãn."},{"en":"I was out of breath after running up the stairs.","vi":"Tôi hụt hơi sau khi chạy lên cầu thang."},{"en":"She held her breath as she opened the letter.","vi":"Cô ấy nín thở khi mở lá thư."}]', '[{"phrase":"take a deep breath"},{"phrase":"out of breath"},{"phrase":"hold your breath"}]', 'breath (n) ≠ breathe (v)', '/breθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bre/breat/breath__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 22, 'increasingly', 'ngày càng', 'adverb', '[{"en":"Online shopping is becoming increasingly popular with older people.","vi":"Mua sắm trực tuyến ngày càng phổ biến với người lớn tuổi."},{"en":"It is increasingly difficult to find a cheap apartment here.","vi":"Ngày càng khó tìm được một căn hộ giá rẻ ở đây."},{"en":"As the weeks passed, he became increasingly worried about his exam.","vi":"Nhiều tuần trôi qua, anh ấy ngày càng lo lắng về kỳ thi."}]', '[{"phrase":"increasingly popular"},{"phrase":"increasingly difficult"},{"phrase":"increasingly important"}]', NULL, '/ɪnˈkriːsɪŋli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incre/increasingly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 23, 'import', 'nhập khẩu', 'verb', '[{"en":"Our country imports most of its oil from abroad.","vi":"Nước ta nhập khẩu phần lớn dầu mỏ từ nước ngoài."},{"en":"This shop sells cheese imported from France.","vi":"Cửa hàng này bán phô mai nhập khẩu từ Pháp."},{"en":"The company plans to import cars from Japan next year.","vi":"Công ty dự định nhập khẩu ô tô từ Nhật Bản vào năm tới."}]', '[{"phrase":"import goods"},{"phrase":"import from"},{"phrase":"imported products"}]', 'import (nhập khẩu) ≠ export (xuất khẩu)', '/ˈɪmpɔːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impor/import__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 24, 'bottle', 'chai, lọ; bình (sữa)', 'noun', '[{"en":"Can you bring me a bottle of water, please?","vi":"Bạn có thể mang cho tôi một chai nước được không?"},{"en":"We opened a bottle of wine to celebrate.","vi":"Chúng tôi đã mở một chai rượu vang để ăn mừng."},{"en":"Babies usually drink milk from a bottle at night.","vi":"Em bé thường uống sữa bằng bình vào ban đêm."}]', '[{"phrase":"bottle of water"},{"phrase":"plastic bottle"},{"phrase":"open a bottle"},{"phrase":"empty bottle"}]', NULL, '/ˈbɑːtl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bot/bottl/bottle__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 25, 'sheet', 'tờ (giấy); ga trải giường', 'noun', '[{"en":"Write your name at the top of the sheet.","vi":"Hãy viết tên của bạn ở đầu tờ giấy."},{"en":"Could you give me a few sheets of paper?","vi":"Bạn có thể đưa cho tôi vài tờ giấy không?"},{"en":"I change the sheets on my bed every week.","vi":"Tôi thay ga trải giường mỗi tuần."}]', '[{"phrase":"sheet of paper"},{"phrase":"change the sheets"},{"phrase":"clean sheets"}]', NULL, '/ʃiːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/she/sheet/sheet__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 26, 'engine', 'động cơ', 'noun', '[{"en":"The engine would not start on such a cold morning.","vi":"Động cơ không chịu khởi động vào buổi sáng lạnh như vậy."},{"en":"He turned off the engine and got out of the car.","vi":"Anh ấy tắt động cơ rồi bước ra khỏi xe."},{"en":"My uncle knows a lot about fixing car engines.","vi":"Chú tôi biết rất nhiều về sửa động cơ ô tô."}]', '[{"phrase":"start the engine"},{"phrase":"turn off the engine"},{"phrase":"car engine"},{"phrase":"engine trouble"}]', NULL, '/ˈendʒɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eng/engin/engine__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 27, 'cast', 'dàn diễn viên; bó bột', 'noun', '[{"en":"The whole cast came back on stage at the end.","vi":"Toàn bộ dàn diễn viên trở lại sân khấu vào cuối buổi diễn."},{"en":"The film has a great cast of young actors.","vi":"Bộ phim có một dàn diễn viên trẻ rất xuất sắc."},{"en":"She broke her arm and had it in a cast for weeks.","vi":"Cô ấy bị gãy tay và phải bó bột trong nhiều tuần."}]', '[{"phrase":"the whole cast"},{"phrase":"cast member"},{"phrase":"in a cast"},{"phrase":"plaster cast"}]', 'động từ: cast – cast – cast', '/kæst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cas/cast_/cast__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 28, 'notion', 'khái niệm; quan niệm, ý niệm', 'noun', '[{"en":"Many people still hold the notion that money brings happiness.","vi":"Nhiều người vẫn giữ quan niệm rằng tiền bạc mang lại hạnh phúc."},{"en":"Young children have no notion of time.","vi":"Trẻ nhỏ không có khái niệm về thời gian."},{"en":"I reject the notion that girls are bad at math.","vi":"Tôi bác bỏ quan niệm rằng con gái học toán kém."}]', '[{"phrase":"the notion that"},{"phrase":"no notion of"},{"phrase":"reject the notion"}]', NULL, '/ˈnəʊʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/not/notio/notion__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 29, 'conservative', 'bảo thủ; thận trọng', 'adjective', '[{"en":"My grandparents have quite conservative ideas about marriage.","vi":"Ông bà tôi có quan điểm khá bảo thủ về hôn nhân."},{"en":"Older people are often more conservative about spending money.","vi":"Người lớn tuổi thường thận trọng hơn trong việc tiêu tiền."},{"en":"Even by a conservative estimate, the repairs will cost a lot.","vi":"Ngay cả theo ước tính thận trọng, việc sửa chữa cũng sẽ tốn nhiều tiền."}]', '[{"phrase":"conservative estimate"},{"phrase":"conservative views"},{"phrase":"deeply conservative"}]', NULL, '/kənˈsɜːrvətɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconservative__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-04', 30, 'journey', 'chuyến đi, hành trình', 'noun', '[{"en":"The journey from Hanoi to Hue takes about twelve hours by train.","vi":"Chuyến đi từ Hà Nội đến Huế mất khoảng mười hai tiếng bằng tàu hỏa."},{"en":"We wished them a safe journey before they left.","vi":"Chúng tôi chúc họ thượng lộ bình an trước khi họ lên đường."},{"en":"Learning a new language is a long journey.","vi":"Học một ngôn ngữ mới là một hành trình dài."}]', '[{"phrase":"long journey"},{"phrase":"safe journey"},{"phrase":"make a journey"},{"phrase":"journey home"}]', NULL, '/ˈdʒɜːrni/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jou/journ/journey__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-4-05', 'ngsl-4', 'Thông dụng 1.501–2.000 · Bộ 5', 'New General Service List, thứ hạng 1.501–2.000', '#3da9fc', 'BookOpen', 5);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 1, 'opposition', 'sự phản đối; đối thủ', 'noun', '[{"en":"There was strong opposition to the new parking rules.","vi":"Có sự phản đối mạnh mẽ đối với quy định đỗ xe mới."},{"en":"Many parents expressed opposition to the plan to close the school.","vi":"Nhiều phụ huynh bày tỏ sự phản đối kế hoạch đóng cửa trường học."},{"en":"Our team faced tough opposition in the final match.","vi":"Đội chúng tôi gặp đối thủ khó chơi trong trận chung kết."}]', '[{"phrase":"strong opposition"},{"phrase":"opposition to"},{"phrase":"face opposition"}]', NULL, '/ˌɑːpəˈzɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/opp/oppos/opposition__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 2, 'relief', 'sự nhẹ nhõm; sự cứu trợ', 'noun', '[{"en":"It was a huge relief to hear that everyone was safe.","vi":"Thật nhẹ nhõm khi nghe tin mọi người đều an toàn."},{"en":"She breathed a sigh of relief when the exam was over.","vi":"Cô ấy thở phào nhẹ nhõm khi kỳ thi kết thúc."},{"en":"Volunteers delivered relief supplies to families after the flood.","vi":"Các tình nguyện viên đã chuyển hàng cứu trợ đến các gia đình sau trận lũ."}]', '[{"phrase":"sigh of relief"},{"phrase":"huge relief"},{"phrase":"relief supplies"},{"phrase":"pain relief"}]', NULL, '/rɪˈliːf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relie/relief__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 3, 'debt', 'nợ; khoản nợ', 'noun', '[{"en":"He worked two jobs to pay off his debt.","vi":"Anh ấy làm hai công việc để trả hết nợ."},{"en":"Many students are in debt when they finish college.","vi":"Nhiều sinh viên đang mắc nợ khi học xong đại học."},{"en":"It is easy to get into debt with a credit card.","vi":"Rất dễ mắc nợ khi dùng thẻ tín dụng."}]', '[{"phrase":"pay off a debt"},{"phrase":"in debt"},{"phrase":"get into debt"}]', 'chữ b không phát âm: /det/', '/det/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/deb/debt_/debt__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 4, 'honor', 'vinh dự; danh dự', 'noun', '[{"en":"It is a great honor to meet you.","vi":"Thật là một vinh dự lớn khi được gặp bạn."},{"en":"Keeping your promises is a matter of honor.","vi":"Giữ lời hứa là vấn đề danh dự."},{"en":"The hotel held a dinner in honor of its oldest employee.","vi":"Khách sạn tổ chức một bữa tối để vinh danh nhân viên lớn tuổi nhất."}]', '[{"phrase":"great honor"},{"phrase":"in honor of"},{"phrase":"matter of honor"}]', 'Anh: honour · Mỹ: honor', '/ˈɑːnər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hon/honou/honour__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 5, 'outcome', 'kết quả', 'noun', '[{"en":"We are still waiting for the outcome of the meeting.","vi":"Chúng tôi vẫn đang chờ kết quả của cuộc họp."},{"en":"Both teams were happy with the final outcome.","vi":"Cả hai đội đều hài lòng với kết quả cuối cùng."},{"en":"Careful planning can lead to a better outcome.","vi":"Lên kế hoạch cẩn thận có thể mang lại kết quả tốt hơn."}]', '[{"phrase":"final outcome"},{"phrase":"outcome of"},{"phrase":"positive outcome"},{"phrase":"successful outcome"}]', NULL, '/ˈaʊtkʌm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/out/outco/outcome__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 6, 'blame', 'đổ lỗi; trách', 'verb', '[{"en":"Don''t blame me for your own mistakes.","vi":"Đừng đổ lỗi cho tôi vì những sai lầm của chính bạn."},{"en":"She blamed the heavy traffic for being late.","vi":"Cô ấy đổ lỗi cho tình trạng kẹt xe vì đã đến muộn."},{"en":"I don''t blame you for feeling upset about it.","vi":"Tôi không trách bạn khi thấy buồn về chuyện đó."}]', '[{"phrase":"blame someone for"},{"phrase":"be to blame"},{"phrase":"blame yourself"}]', NULL, '/bleɪm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bla/blame/blame__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 7, 'explanation', 'lời giải thích', 'noun', '[{"en":"The teacher gave a clear explanation of the grammar rule.","vi":"Giáo viên đưa ra lời giải thích rõ ràng về quy tắc ngữ pháp."},{"en":"Is there any explanation for why the train was late?","vi":"Có lời giải thích nào cho việc tàu đến muộn không?"},{"en":"He left the room without a word of explanation.","vi":"Anh ấy rời khỏi phòng mà không một lời giải thích."}]', '[{"phrase":"clear explanation"},{"phrase":"give an explanation"},{"phrase":"explanation for"},{"phrase":"explanation of"}]', NULL, '/ˌekspləˈneɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expla/explanation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 8, 'arise', 'nảy sinh; phát sinh', 'verb', '[{"en":"Problems may arise if you don''t read the instructions.","vi":"Vấn đề có thể nảy sinh nếu bạn không đọc hướng dẫn."},{"en":"Call me if any questions arise during the trip.","vi":"Hãy gọi cho tôi nếu có thắc mắc nào phát sinh trong chuyến đi."},{"en":"A problem arose when we tried to book the hotel.","vi":"Một vấn đề đã phát sinh khi chúng tôi đặt phòng khách sạn."}]', '[{"phrase":"problems arise"},{"phrase":"questions arise"},{"phrase":"if the need arises"}]', 'arise – arose – arisen', '/əˈraɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ari/arise/arise__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 9, 'musical', 'thuộc về âm nhạc; có năng khiếu âm nhạc', 'adjective', '[{"en":"Do you play any musical instruments, such as the piano?","vi":"Bạn có chơi nhạc cụ nào không, chẳng hạn như piano?"},{"en":"Everyone in her family is very musical.","vi":"Mọi người trong gia đình cô ấy đều rất có năng khiếu âm nhạc."},{"en":"His musical talent was clear from a young age.","vi":"Tài năng âm nhạc của cậu ấy đã bộc lộ từ khi còn nhỏ."}]', '[{"phrase":"musical instrument"},{"phrase":"musical talent"},{"phrase":"musical ability"}]', NULL, '/ˈmjuːzɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mus/music/musical__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 10, 'recover', 'hồi phục; tìm lại được', 'verb', '[{"en":"It took him three months to recover from the accident.","vi":"Anh ấy mất ba tháng để hồi phục sau tai nạn."},{"en":"I hope you recover quickly from your cold.","vi":"Mong bạn mau khỏi cảm."},{"en":"The police recovered the stolen bike two days later.","vi":"Hai ngày sau, cảnh sát đã tìm lại được chiếc xe đạp bị đánh cắp."}]', '[{"phrase":"recover from"},{"phrase":"fully recover"},{"phrase":"recover quickly"}]', NULL, '/rɪˈkʌvər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recov/recover__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 11, 'dad', 'bố; ba', 'noun', '[{"en":"My dad taught me how to ride a bike.","vi":"Bố tôi đã dạy tôi đi xe đạp."},{"en":"Dad, can you pick me up after school today?","vi":"Bố ơi, hôm nay bố đón con sau giờ học được không?"},{"en":"She calls her dad every Sunday evening.","vi":"Cô ấy gọi điện cho bố vào mỗi tối Chủ nhật."}]', '[{"phrase":"my dad"},{"phrase":"mom and dad"}]', NULL, '/dæd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dad/dad__/dad__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 12, 'stretch', 'duỗi; vươn mình; kéo giãn', 'verb', '[{"en":"Always stretch your legs before you go running.","vi":"Hãy luôn giãn cơ chân trước khi chạy bộ."},{"en":"The cat woke up and stretched in the sun.","vi":"Con mèo thức dậy và vươn mình dưới nắng."},{"en":"Don''t stretch my sweater, or it will lose its shape.","vi":"Đừng kéo giãn áo len của tôi, không thì nó sẽ bị mất dáng."}]', '[{"phrase":"stretch your legs"},{"phrase":"stretch out"},{"phrase":"stretch your arms"}]', NULL, '/stretʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stret/stretch__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 13, 'declare', 'tuyên bố; khai báo', 'verb', '[{"en":"The judges declared her the winner of the competition.","vi":"Ban giám khảo tuyên bố cô ấy là người chiến thắng cuộc thi."},{"en":"I had nothing to declare, so I walked through customs.","vi":"Tôi không có gì cần khai báo nên đi thẳng qua hải quan."},{"en":"He declared that he would never smoke again.","vi":"Anh ấy tuyên bố sẽ không bao giờ hút thuốc nữa."}]', '[{"phrase":"officially declare"},{"phrase":"declare income"},{"phrase":"nothing to declare"}]', NULL, '/dɪˈkler/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dec/decla/declare__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 14, 'retire', 'nghỉ hưu', 'verb', '[{"en":"My grandfather retired at the age of sixty-five.","vi":"Ông tôi nghỉ hưu năm sáu mươi lăm tuổi."},{"en":"She plans to retire early and move to the countryside.","vi":"Bà ấy dự định nghỉ hưu sớm và chuyển về vùng quê."},{"en":"After he retires, he wants to travel around the world.","vi":"Sau khi nghỉ hưu, ông ấy muốn đi du lịch vòng quanh thế giới."}]', '[{"phrase":"retire early"},{"phrase":"retire from"},{"phrase":"retire at"}]', NULL, '/rɪˈtaɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ret/retir/retire__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 15, 'tiny', 'rất nhỏ; bé xíu', 'adjective', '[{"en":"They live in a tiny apartment in the city center.","vi":"Họ sống trong một căn hộ rất nhỏ ở trung tâm thành phố."},{"en":"The baby grabbed my finger with her tiny hand.","vi":"Em bé nắm lấy ngón tay tôi bằng bàn tay bé xíu."},{"en":"There is only a tiny difference between the two photos.","vi":"Chỉ có một khác biệt rất nhỏ giữa hai bức ảnh."}]', '[{"phrase":"a tiny bit"},{"phrase":"tiny amount"},{"phrase":"tiny apartment"}]', NULL, '/ˈtaɪni/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tin/tiny_/tiny__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 16, 'careful', 'cẩn thận; kỹ lưỡng', 'adjective', '[{"en":"Be careful when you cross the street.","vi":"Hãy cẩn thận khi bạn băng qua đường."},{"en":"She is very careful with her money.","vi":"Cô ấy rất cẩn thận trong chuyện tiền bạc."},{"en":"After careful thought, we decided not to buy the house.","vi":"Sau khi suy nghĩ kỹ lưỡng, chúng tôi quyết định không mua căn nhà."}]', '[{"phrase":"be careful"},{"phrase":"careful with"},{"phrase":"careful thought"},{"phrase":"careful planning"}]', NULL, '/ˈkerfl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/car/caref/careful__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 17, 'suitable', 'phù hợp; thích hợp', 'adjective', '[{"en":"This movie is not suitable for young children.","vi":"Bộ phim này không phù hợp với trẻ nhỏ."},{"en":"We are looking for a suitable place to have the party.","vi":"Chúng tôi đang tìm một địa điểm phù hợp để tổ chức bữa tiệc."},{"en":"Please wear suitable shoes for the long walk.","vi":"Hãy mang giày thích hợp cho chuyến đi bộ dài."}]', '[{"phrase":"suitable for"},{"phrase":"suitable place"},{"phrase":"suitable time"}]', NULL, '/ˈsuːtəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sui/suita/suitable__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 18, 'native', 'bản xứ; bản địa; thuộc nơi sinh ra', 'adjective', '[{"en":"She is a native speaker of Spanish.","vi":"Cô ấy là người bản xứ nói tiếng Tây Ban Nha."},{"en":"He returned to his native country after ten years abroad.","vi":"Anh ấy trở về quê hương sau mười năm sống ở nước ngoài."},{"en":"These flowers are native to South America.","vi":"Những loài hoa này có nguồn gốc từ Nam Mỹ."}]', '[{"phrase":"native speaker"},{"phrase":"native language"},{"phrase":"native country"},{"phrase":"native to"}]', NULL, '/ˈneɪtɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nat/nativ/native__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 19, 'fruit', 'trái cây; hoa quả', 'noun', '[{"en":"You should eat more fresh fruit and vegetables.","vi":"Bạn nên ăn nhiều trái cây tươi và rau hơn."},{"en":"We bought some fruit at the market this morning.","vi":"Sáng nay chúng tôi đã mua ít trái cây ở chợ."},{"en":"Which fruit do you like best, apples or oranges?","vi":"Bạn thích loại quả nào nhất, táo hay cam?"}]', '[{"phrase":"fresh fruit"},{"phrase":"fruit juice"},{"phrase":"piece of fruit"}]', 'thường không đếm được: some fruit', '/fruːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fru/fruit/fruit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 20, 'analyze', 'phân tích', 'verb', '[{"en":"Scientists analyzed the water to see if it was safe.","vi":"Các nhà khoa học đã phân tích nước để xem nó có an toàn không."},{"en":"Let''s analyze why our sales dropped last month.","vi":"Hãy phân tích lý do doanh số giảm vào tháng trước."},{"en":"It takes time to analyze all this data carefully.","vi":"Cần có thời gian để phân tích kỹ tất cả dữ liệu này."}]', '[{"phrase":"analyze data"},{"phrase":"carefully analyze"},{"phrase":"analyze the results"}]', 'Anh: analyse · Mỹ: analyze', '/ˈænəˌlaɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 21, 'witness', 'nhân chứng; người chứng kiến', 'noun', '[{"en":"The police are looking for witnesses to the accident.","vi":"Cảnh sát đang tìm nhân chứng của vụ tai nạn."},{"en":"A witness said the car was going very fast.","vi":"Một nhân chứng nói rằng chiếc xe chạy rất nhanh."},{"en":"She was the only witness when the window broke.","vi":"Cô ấy là người chứng kiến duy nhất khi cửa sổ bị vỡ."}]', '[{"phrase":"key witness"},{"phrase":"witness to"},{"phrase":"the only witness"}]', NULL, '/ˈwɪtnəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wit/witne/witness__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 22, 'mail', 'thư từ; bưu phẩm', 'noun', '[{"en":"Did any mail come for me today?","vi":"Hôm nay có thư nào gửi cho tôi không?"},{"en":"I check my mail every morning before work.","vi":"Tôi kiểm tra thư mỗi sáng trước khi đi làm."},{"en":"The package should arrive in the mail next week.","vi":"Gói hàng chắc sẽ đến qua đường bưu điện vào tuần sau."}]', '[{"phrase":"check your mail"},{"phrase":"in the mail"},{"phrase":"junk mail"}]', 'không đếm được', '/meɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mai/mail_/mail__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 23, 'terrible', 'kinh khủng; tồi tệ', 'adjective', '[{"en":"The food at that restaurant was terrible.","vi":"Đồ ăn ở nhà hàng đó thật tồi tệ."},{"en":"I have a terrible headache this morning.","vi":"Sáng nay tôi bị đau đầu kinh khủng."},{"en":"I feel terrible about forgetting your birthday.","vi":"Tôi thấy thật tệ vì đã quên sinh nhật bạn."}]', '[{"phrase":"feel terrible"},{"phrase":"terrible mistake"},{"phrase":"terrible weather"}]', NULL, '/ˈterəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ter/terri/terrible__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 24, 'researcher', 'nhà nghiên cứu', 'noun', '[{"en":"The researchers asked five hundred people about their sleeping habits.","vi":"Các nhà nghiên cứu đã hỏi năm trăm người về thói quen ngủ của họ."},{"en":"My sister works as a medical researcher at a university.","vi":"Chị tôi làm nhà nghiên cứu y khoa tại một trường đại học."},{"en":"Researchers have found that walking every day is good for your heart.","vi":"Các nhà nghiên cứu đã phát hiện rằng đi bộ mỗi ngày tốt cho tim."}]', '[{"phrase":"medical researcher"},{"phrase":"team of researchers"},{"phrase":"market researcher"}]', NULL, '/ˈriːsɜːrtʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resea/researcher__us_6.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 25, 'ordinary', 'bình thường; thông thường', 'adjective', '[{"en":"It was just an ordinary day at the office.","vi":"Đó chỉ là một ngày bình thường ở văn phòng."},{"en":"Ordinary people can''t afford such expensive houses.","vi":"Người bình thường không đủ tiền mua những ngôi nhà đắt như vậy."},{"en":"The hotel room looked quite ordinary, but the view was amazing.","vi":"Phòng khách sạn trông khá bình thường, nhưng cảnh nhìn ra thì tuyệt vời."}]', '[{"phrase":"ordinary people"},{"phrase":"ordinary life"},{"phrase":"out of the ordinary"}]', NULL, '/ˈɔːrdneri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ord/ordin/ordinary__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 26, 'selection', 'sự lựa chọn; sự tuyển chọn', 'noun', '[{"en":"The market has a wide selection of fresh vegetables.","vi":"Chợ có rất nhiều loại rau tươi để lựa chọn."},{"en":"Her selection for the national team made her parents proud.","vi":"Việc cô ấy được chọn vào đội tuyển quốc gia khiến bố mẹ tự hào."},{"en":"The final selection of players will be announced on Friday.","vi":"Danh sách cầu thủ được chọn cuối cùng sẽ được công bố vào thứ Sáu."}]', '[{"phrase":"wide selection"},{"phrase":"selection of"},{"phrase":"final selection"},{"phrase":"selection process"}]', NULL, '/sɪˈlekʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sel/selec/selection__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 27, 'anywhere', 'bất cứ đâu; (ở) đâu đó', 'adverb', '[{"en":"You can sit anywhere you like in the classroom.","vi":"Bạn có thể ngồi bất cứ chỗ nào bạn thích trong lớp học."},{"en":"I can''t find my phone anywhere in the house.","vi":"Tôi không tìm thấy điện thoại ở đâu trong nhà cả."},{"en":"Are you going anywhere nice for the holidays this year?","vi":"Kỳ nghỉ năm nay bạn có đi đâu thú vị không?"}]', '[{"phrase":"anywhere else"},{"phrase":"go anywhere"},{"phrase":"anywhere you like"}]', NULL, '/ˈeniwer/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/any/anywh/anywhere__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 28, 'mental', 'thuộc về tinh thần; trí óc', 'adjective', '[{"en":"Exercise is good for both physical and mental health.","vi":"Tập thể dục tốt cho cả sức khỏe thể chất lẫn tinh thần."},{"en":"Try to do some simple mental math without a calculator.","vi":"Hãy thử tính nhẩm vài phép đơn giản mà không dùng máy tính."},{"en":"Working long hours can cause a lot of mental stress.","vi":"Làm việc nhiều giờ liền có thể gây ra nhiều căng thẳng tinh thần."}]', '[{"phrase":"mental health"},{"phrase":"mental stress"},{"phrase":"mental math"}]', NULL, '/ˈmentl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/men/menta/mental__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 29, 'participant', 'người tham gia', 'noun', '[{"en":"Each participant will receive a free T-shirt.","vi":"Mỗi người tham gia sẽ nhận được một chiếc áo phông miễn phí."},{"en":"She was an active participant in every class discussion.","vi":"Cô ấy là người tham gia tích cực trong mọi buổi thảo luận trên lớp."},{"en":"All participants must register before the race starts.","vi":"Tất cả người tham gia phải đăng ký trước khi cuộc đua bắt đầu."}]', '[{"phrase":"active participant"},{"phrase":"participant in"},{"phrase":"all participants"}]', NULL, '/pɑːrˈtɪsɪpənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/parti/participant__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-05', 30, 'vision', 'thị lực; tầm nhìn', 'noun', '[{"en":"My vision is getting worse, so I need new glasses.","vi":"Thị lực của tôi đang kém đi nên tôi cần kính mới."},{"en":"The eye doctor tested my vision this morning.","vi":"Sáng nay bác sĩ mắt đã kiểm tra thị lực của tôi."},{"en":"The new manager has a clear vision for the company''s future.","vi":"Người quản lý mới có tầm nhìn rõ ràng cho tương lai của công ty."}]', '[{"phrase":"clear vision"},{"phrase":"poor vision"},{"phrase":"vision for the future"}]', NULL, '/ˈvɪʒn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vis/visio/vision__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-4-06', 'ngsl-4', 'Thông dụng 1.501–2.000 · Bộ 6', 'New General Service List, thứ hạng 1.501–2.000', '#3da9fc', 'BookOpen', 6);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 1, 'personality', 'tính cách; cá tính', 'noun', '[{"en":"She has a warm personality and makes friends easily.","vi":"Cô ấy có tính cách ấm áp và dễ kết bạn."},{"en":"His personality changed a lot after he started university.","vi":"Tính cách của anh ấy đã thay đổi nhiều sau khi vào đại học."},{"en":"It''s important to find a job that suits your personality.","vi":"Điều quan trọng là tìm được công việc phù hợp với tính cách của bạn."}]', '[{"phrase":"warm personality"},{"phrase":"strong personality"},{"phrase":"personality trait"}]', NULL, '/ˌpɜːrsəˈnæləti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perso/personality__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 2, 'specifically', 'cụ thể; riêng (cho)', 'adverb', '[{"en":"The course was designed specifically for beginners.","vi":"Khóa học được thiết kế riêng cho người mới bắt đầu."},{"en":"I specifically asked you not to tell anyone.","vi":"Tôi đã dặn rõ là bạn không được kể với ai."},{"en":"More specifically, we need someone who can speak Japanese.","vi":"Cụ thể hơn, chúng tôi cần một người nói được tiếng Nhật."}]', '[{"phrase":"designed specifically for"},{"phrase":"more specifically"},{"phrase":"specifically mention"}]', NULL, '/spəˈsɪfɪkli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speci/specifically__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 3, 'fat', 'béo, mập; dày', 'adjective', '[{"en":"Our cat got fat because we fed her too much.","vi":"Con mèo nhà chúng tôi béo lên vì chúng tôi cho nó ăn quá nhiều."},{"en":"He was worried that he was getting fat.","vi":"Anh ấy lo rằng mình đang béo lên."},{"en":"She handed me a fat envelope full of old photos.","vi":"Cô ấy đưa tôi một phong bì dày cộp đầy ảnh cũ."}]', '[{"phrase":"get fat"},{"phrase":"grow fat"}]', 'fat – fatter – fattest; nói về người có thể bị coi là bất lịch sự', '/fæt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fat/fat__/fat__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 4, 'entry', 'sự vào, quyền vào; mục ghi; bài dự thi', 'noun', '[{"en":"Entry to the museum is free on Sundays.","vi":"Vào cửa bảo tàng được miễn phí vào các ngày Chủ nhật."},{"en":"I wrote a short diary entry before bed.","vi":"Tôi viết một trang nhật ký ngắn trước khi đi ngủ."},{"en":"The winning entry was a photo of a sleeping child.","vi":"Bài dự thi đoạt giải là bức ảnh một đứa trẻ đang ngủ."}]', '[{"phrase":"free entry"},{"phrase":"entry fee"},{"phrase":"diary entry"},{"phrase":"winning entry"}]', NULL, '/ˈentri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ent/entry/entry__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 5, 'fellow', 'đồng (nghiệp, học…); cùng cảnh', 'adjective', '[{"en":"She gets along well with her fellow students.","vi":"Cô ấy hòa hợp với các bạn cùng học."},{"en":"He shared his lunch with a fellow passenger on the train.","vi":"Anh ấy chia bữa trưa với một hành khách đi cùng trên tàu."},{"en":"My fellow workers threw me a party on my last day.","vi":"Các đồng nghiệp đã tổ chức tiệc cho tôi vào ngày làm việc cuối cùng."}]', '[{"phrase":"fellow students"},{"phrase":"fellow passengers"},{"phrase":"fellow citizens"}]', 'chỉ đứng trước danh từ; (n) gã, anh chàng', '/ˈfeləʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fel/fello/fellow__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 6, 'chemical', 'hóa chất; chất hóa học', 'noun', '[{"en":"Wear gloves when you use strong cleaning chemicals.","vi":"Hãy đeo găng tay khi dùng các hóa chất tẩy rửa mạnh."},{"en":"The factory was fined for dumping chemicals into the river.","vi":"Nhà máy bị phạt vì xả hóa chất xuống sông."},{"en":"These vegetables are grown without any harmful chemicals.","vi":"Những loại rau này được trồng mà không dùng hóa chất độc hại nào."}]', '[{"phrase":"harmful chemicals"},{"phrase":"toxic chemicals"},{"phrase":"cleaning chemicals"}]', '(adj) thuộc hóa học: chemical reaction', '/ˈkemɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/che/chemi/chemical__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 7, 'capture', 'bắt giữ; ghi lại (hình ảnh); thu hút', 'verb', '[{"en":"Zoo workers captured the escaped monkey near the river.","vi":"Nhân viên sở thú đã bắt được con khỉ xổng chuồng gần bờ sông."},{"en":"This photo really captures the beauty of the old town.","vi":"Bức ảnh này thực sự ghi lại được vẻ đẹp của phố cổ."},{"en":"The story captured the attention of readers all over the country.","vi":"Câu chuyện đã thu hút sự chú ý của độc giả khắp cả nước."}]', '[{"phrase":"capture attention"},{"phrase":"capture the moment"},{"phrase":"capture the imagination"}]', NULL, '/ˈkæptʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cap/captu/capture__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 8, 'tip', 'tiền boa; lời khuyên, mẹo; đầu, chóp', 'noun', '[{"en":"We left a generous tip because the service was excellent.","vi":"Chúng tôi để lại tiền boa hậu hĩnh vì phục vụ rất tốt."},{"en":"Can you give me some tips for my first job interview?","vi":"Bạn có thể cho tôi vài lời khuyên cho buổi phỏng vấn xin việc đầu tiên không?"},{"en":"I burned the tip of my tongue on the hot soup.","vi":"Tôi bị bỏng đầu lưỡi vì món súp nóng."}]', '[{"phrase":"leave a tip"},{"phrase":"generous tip"},{"phrase":"useful tips"}]', NULL, '/tɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tip/tip__/tip__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 9, 'discount', 'sự giảm giá; khoản chiết khấu', 'noun', '[{"en":"Students get a ten percent discount at this bookstore.","vi":"Sinh viên được giảm giá mười phần trăm ở hiệu sách này."},{"en":"Is there a discount if we buy two tickets?","vi":"Nếu mua hai vé thì có được giảm giá không?"},{"en":"She bought the shoes at a big discount during the sale.","vi":"Cô ấy mua đôi giày với giá giảm mạnh trong đợt khuyến mãi."}]', '[{"phrase":"get a discount"},{"phrase":"offer a discount"},{"phrase":"student discount"},{"phrase":"big discount"}]', NULL, '/ˈdɪskaʊnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disco/discount__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 10, 'peak', 'đỉnh (núi); đỉnh điểm, cao điểm', 'noun', '[{"en":"We finally reached the peak just before sunset.","vi":"Cuối cùng chúng tôi cũng lên tới đỉnh núi ngay trước hoàng hôn."},{"en":"The heat was at its peak around two in the afternoon.","vi":"Cái nóng lên đến đỉnh điểm vào khoảng hai giờ chiều."},{"en":"She was at the peak of her career in her forties.","vi":"Bà ấy ở đỉnh cao sự nghiệp khi ngoài bốn mươi tuổi."}]', '[{"phrase":"at its peak"},{"phrase":"mountain peak"},{"phrase":"peak hours"},{"phrase":"peak season"}]', NULL, '/piːk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pea/peak_/peak__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 11, 'chairman', 'chủ tịch', 'noun', '[{"en":"The chairman opened the meeting with a short speech.","vi":"Chủ tịch khai mạc cuộc họp bằng một bài phát biểu ngắn."},{"en":"He was elected chairman of the club last year.","vi":"Ông ấy được bầu làm chủ tịch câu lạc bộ vào năm ngoái."},{"en":"My uncle has been chairman of the company for ten years.","vi":"Chú tôi đã làm chủ tịch công ty được mười năm."}]', '[{"phrase":"company chairman"},{"phrase":"elected chairman"},{"phrase":"chairman of the board"}]', 'số nhiều: chairmen', '/ˈtʃermən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chair/chairman__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 12, 'proportion', 'tỷ lệ; phần', 'noun', '[{"en":"A large proportion of our customers are young people.","vi":"Một phần lớn khách hàng của chúng tôi là người trẻ."},{"en":"The proportion of women in the company has increased.","vi":"Tỷ lệ phụ nữ trong công ty đã tăng lên."},{"en":"Mix the flour and water in the right proportions.","vi":"Trộn bột và nước theo đúng tỷ lệ."}]', '[{"phrase":"large proportion"},{"phrase":"high proportion"},{"phrase":"in proportion to"}]', NULL, '/prəˈpɔːrʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/propo/proportion__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 13, 'ear', 'tai', 'noun', '[{"en":"She whispered something in my ear during the movie.","vi":"Cô ấy thì thầm gì đó vào tai tôi trong lúc xem phim."},{"en":"The loud music at the concert hurt my ears.","vi":"Tiếng nhạc lớn ở buổi hòa nhạc làm tôi đau tai."},{"en":"My daughter wants to get her ears pierced for her birthday.","vi":"Con gái tôi muốn đi bấm lỗ tai nhân dịp sinh nhật."}]', '[{"phrase":"whisper in someone''s ear"},{"phrase":"ear infection"},{"phrase":"pierced ears"}]', NULL, '/ɪr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ear/ear__/ear__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 14, 'disappear', 'biến mất; mất tích', 'verb', '[{"en":"The sun slowly disappeared behind the dark clouds.","vi":"Mặt trời từ từ biến mất sau những đám mây đen."},{"en":"My keys seem to disappear every time I''m in a hurry.","vi":"Chìa khóa của tôi dường như biến mất mỗi khi tôi vội."},{"en":"Many small shops have disappeared from this street.","vi":"Nhiều cửa hàng nhỏ đã biến mất khỏi con phố này."}]', '[{"phrase":"disappear completely"},{"phrase":"suddenly disappear"},{"phrase":"disappear from view"}]', NULL, '/ˌdɪsəˈpɪr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disap/disappear__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 15, 'shout', 'hét, la to; quát', 'verb', '[{"en":"Please don''t shout, because the baby is sleeping.","vi":"Làm ơn đừng hét, em bé đang ngủ."},{"en":"He shouted at his brother for breaking his phone.","vi":"Anh ấy quát em trai vì làm vỡ điện thoại của mình."},{"en":"We had to shout to be heard over the music.","vi":"Chúng tôi phải hét to mới át được tiếng nhạc."}]', '[{"phrase":"shout at someone"},{"phrase":"shout for help"},{"phrase":"shout loudly"}]', NULL, '/ʃaʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/shout/shout__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 16, 'yard', 'sân (nhà); thước Anh (≈ 0,9 m)', 'noun', '[{"en":"The kids are playing soccer in the yard.","vi":"Bọn trẻ đang chơi bóng đá ngoài sân."},{"en":"We have a small yard behind our house.","vi":"Nhà chúng tôi có một khoảng sân nhỏ phía sau."},{"en":"The bus stop is only a hundred yards from here.","vi":"Trạm xe buýt chỉ cách đây một trăm thước Anh."}]', '[{"phrase":"front yard"},{"phrase":"back yard"},{"phrase":"a few yards"}]', NULL, '/jɑːrd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/y/yar/yard_/yard__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 17, 'constant', 'liên tục, không ngừng; không đổi', 'adjective', '[{"en":"The constant noise from the street kept me awake.","vi":"Tiếng ồn liên tục ngoài đường khiến tôi không ngủ được."},{"en":"Young babies need constant care and attention from their parents.","vi":"Trẻ sơ sinh cần được cha mẹ chăm sóc và quan tâm liên tục."},{"en":"Keep the oven at a constant temperature while baking.","vi":"Giữ lò ở nhiệt độ không đổi trong khi nướng bánh."}]', '[{"phrase":"constant noise"},{"phrase":"constant attention"},{"phrase":"constant temperature"}]', NULL, '/ˈkɑːnstənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconstant__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 18, 'significantly', 'đáng kể', 'adverb', '[{"en":"Prices have risen significantly over the past year.","vi":"Giá cả đã tăng đáng kể trong năm qua."},{"en":"Regular exercise can significantly improve your sleep.","vi":"Tập thể dục đều đặn có thể cải thiện đáng kể giấc ngủ của bạn."},{"en":"This phone is significantly cheaper than the one I bought.","vi":"Chiếc điện thoại này rẻ hơn đáng kể so với chiếc tôi đã mua."}]', '[{"phrase":"increase significantly"},{"phrase":"significantly improve"},{"phrase":"significantly different"}]', NULL, '/sɪɡˈnɪfɪkəntli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sig/signi/significantly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 19, 'hill', 'đồi; dốc', 'noun', '[{"en":"Our house is at the top of a steep hill.","vi":"Nhà chúng tôi nằm trên đỉnh một con dốc cao."},{"en":"We walked up the hill to watch the sunrise.","vi":"Chúng tôi đi bộ lên đồi để ngắm bình minh."},{"en":"The village is surrounded by green hills and rice fields.","vi":"Ngôi làng được bao quanh bởi những ngọn đồi xanh và cánh đồng lúa."}]', '[{"phrase":"steep hill"},{"phrase":"top of the hill"},{"phrase":"up the hill"}]', NULL, '/hɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hil/hill_/hill__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 20, 'considerable', 'đáng kể, khá lớn', 'adjective', '[{"en":"Learning a new language takes a considerable amount of time.","vi":"Học một ngôn ngữ mới cần một lượng thời gian đáng kể."},{"en":"The storm caused considerable damage to homes along the coast.","vi":"Cơn bão gây thiệt hại đáng kể cho nhà cửa dọc bờ biển."},{"en":"She has considerable experience in teaching young children.","vi":"Cô ấy có khá nhiều kinh nghiệm dạy trẻ nhỏ."}]', '[{"phrase":"considerable amount"},{"phrase":"considerable damage"},{"phrase":"considerable experience"}]', NULL, '/kənˈsɪdərəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsiderable__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 21, 'instruction', 'hướng dẫn; chỉ dẫn, chỉ thị', 'noun', '[{"en":"Read the instructions carefully before you start the exam.","vi":"Hãy đọc kỹ hướng dẫn trước khi bắt đầu làm bài thi."},{"en":"If you follow the instructions, the machine is easy to use.","vi":"Nếu làm theo hướng dẫn thì chiếc máy này rất dễ dùng."},{"en":"The manager gave clear instructions to all new staff.","vi":"Quản lý đã đưa ra chỉ dẫn rõ ràng cho tất cả nhân viên mới."}]', '[{"phrase":"follow instructions"},{"phrase":"clear instructions"},{"phrase":"give instructions"}]', 'thường dùng số nhiều: instructions', '/ɪnˈstrʌkʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/instr/instruction__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 22, 'intelligence', 'trí thông minh; tình báo', 'noun', '[{"en":"Dolphins are known for their high intelligence.","vi":"Cá heo nổi tiếng là có trí thông minh cao."},{"en":"It takes intelligence and patience to solve this puzzle.","vi":"Cần có trí thông minh và sự kiên nhẫn để giải câu đố này."},{"en":"He worked for military intelligence before becoming a teacher.","vi":"Ông ấy từng làm cho cơ quan tình báo quân đội trước khi trở thành giáo viên."}]', '[{"phrase":"high intelligence"},{"phrase":"artificial intelligence"},{"phrase":"military intelligence"}]', NULL, '/ɪnˈtelɪdʒəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/intel/intelligence__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 23, 'ideal', 'lý tưởng', 'adjective', '[{"en":"This quiet beach is ideal for a family vacation.","vi":"Bãi biển yên tĩnh này rất lý tưởng cho kỳ nghỉ gia đình."},{"en":"In an ideal world, everyone would have a job they love.","vi":"Trong một thế giới lý tưởng, ai cũng sẽ có công việc mình yêu thích."},{"en":"The weather was ideal for a long bike ride.","vi":"Thời tiết rất lý tưởng cho một chuyến đạp xe dài."}]', '[{"phrase":"ideal for"},{"phrase":"ideal world"},{"phrase":"ideal place"},{"phrase":"ideal solution"}]', NULL, '/aɪˈdiːəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ide/ideal/ideal__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 24, 'folk', 'người, dân; dân gian', 'noun', '[{"en":"Country folk are often friendlier than people in big cities.","vi":"Người dân quê thường thân thiện hơn người ở thành phố lớn."},{"en":"My folks live in a small town near the coast.","vi":"Bố mẹ tôi sống ở một thị trấn nhỏ gần biển."},{"en":"She loves listening to traditional folk songs from her hometown.","vi":"Cô ấy thích nghe những bài dân ca truyền thống của quê mình."}]', '[{"phrase":"folk music"},{"phrase":"folk song"},{"phrase":"country folk"},{"phrase":"old folks"}]', 'folks (thân mật): mọi người; bố mẹ', '/fəʊk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fol/folk_/folk__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 25, 'surely', 'chắc chắn; chắc hẳn, lẽ nào', 'adverb', '[{"en":"Surely you don''t expect me to finish this by tomorrow?","vi":"Lẽ nào bạn muốn tôi làm xong việc này trước ngày mai sao?"},{"en":"The work is going slowly but surely, so we''ll finish soon.","vi":"Công việc tiến triển chậm mà chắc, nên chúng tôi sẽ sớm xong."},{"en":"Surely someone in the office knows how to fix this printer.","vi":"Chắc hẳn ai đó trong văn phòng biết cách sửa cái máy in này."}]', '[{"phrase":"slowly but surely"},{"phrase":"surely not"}]', NULL, '/ˈʃʊrli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/surel/surely__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 26, 'guard', 'người bảo vệ, lính gác; sự canh gác', 'noun', '[{"en":"A security guard checked our bags at the entrance.","vi":"Một nhân viên bảo vệ đã kiểm tra túi của chúng tôi ở lối vào."},{"en":"The guards at the gate asked to see our passports.","vi":"Lính gác ở cổng yêu cầu xem hộ chiếu của chúng tôi."},{"en":"Two soldiers stood guard outside the old palace.","vi":"Hai người lính đứng canh gác bên ngoài cung điện cũ."}]', '[{"phrase":"security guard"},{"phrase":"stand guard"},{"phrase":"border guard"}]', '(v) canh gác, bảo vệ', '/ɡɑːrd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gua/guard/guard__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 27, 'cat', 'con mèo', 'noun', '[{"en":"Our cat sleeps on the sofa most of the day.","vi":"Con mèo nhà tôi ngủ trên ghế sofa gần như cả ngày."},{"en":"She feeds the stray cats in her neighborhood every evening.","vi":"Tối nào cô ấy cũng cho những con mèo hoang trong khu phố ăn."},{"en":"Do you prefer cats or dogs as pets?","vi":"Bạn thích nuôi mèo hay chó hơn?"}]', '[{"phrase":"pet cat"},{"phrase":"stray cat"},{"phrase":"feed the cat"}]', NULL, '/kæt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cat/cat__/cat__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 28, 'somewhat', 'hơi, có phần; phần nào', 'adverb', '[{"en":"I was somewhat surprised by her answer.","vi":"Tôi hơi ngạc nhiên trước câu trả lời của cô ấy."},{"en":"The situation has improved somewhat since last month.","vi":"Tình hình đã cải thiện phần nào kể từ tháng trước."},{"en":"The movie was somewhat longer than I had expected.","vi":"Bộ phim dài hơn tôi nghĩ một chút."}]', '[{"phrase":"somewhat surprised"},{"phrase":"somewhat different"},{"phrase":"improve somewhat"}]', NULL, '/ˈsʌmwʌt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/som/somew/somewhat__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 29, 'kiss', 'hôn', 'verb', '[{"en":"She kissed her son goodbye at the school gate.","vi":"Cô ấy hôn tạm biệt con trai ở cổng trường."},{"en":"My grandmother always kisses me on the cheek.","vi":"Bà tôi lúc nào cũng hôn lên má tôi."},{"en":"The couple kissed when the clock struck midnight.","vi":"Cặp đôi hôn nhau khi đồng hồ điểm nửa đêm."}]', '[{"phrase":"kiss goodbye"},{"phrase":"kiss someone on the cheek"},{"phrase":"kiss each other"}]', '(n) nụ hôn', '/kɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kis/kiss_/kiss__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-06', 30, 'presentation', 'bài thuyết trình; sự trình bày', 'noun', '[{"en":"I have to give a presentation to the whole class tomorrow.","vi":"Ngày mai tôi phải thuyết trình trước cả lớp."},{"en":"Her presentation on healthy eating was clear and interesting.","vi":"Bài thuyết trình của cô ấy về ăn uống lành mạnh rất rõ ràng và thú vị."},{"en":"At a restaurant, the presentation of the food matters too.","vi":"Ở nhà hàng, cách trình bày món ăn cũng quan trọng."}]', '[{"phrase":"give a presentation"},{"phrase":"make a presentation"},{"phrase":"presentation skills"}]', NULL, '/ˌpriːznˈteɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prese/presentation__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-4-07', 'ngsl-4', 'Thông dụng 1.501–2.000 · Bộ 7', 'New General Service List, thứ hạng 1.501–2.000', '#3da9fc', 'BookOpen', 7);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 1, 'joint', 'chung; phối hợp', 'adjective', '[{"en":"My wife and I opened a joint bank account last year.","vi":"Vợ tôi và tôi đã mở một tài khoản ngân hàng chung vào năm ngoái."},{"en":"The two schools organized a joint event for parents.","vi":"Hai trường đã tổ chức một sự kiện chung dành cho phụ huynh."},{"en":"The report was a joint effort by the whole team.","vi":"Bản báo cáo là nỗ lực chung của cả nhóm."}]', '[{"phrase":"joint account"},{"phrase":"joint effort"},{"phrase":"joint decision"},{"phrase":"joint venture"}]', NULL, '/dʒɔɪnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/joi/joint/joint__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 2, 'compete', 'cạnh tranh; thi đấu', 'verb', '[{"en":"Small shops find it hard to compete with big supermarkets.","vi":"Các cửa hàng nhỏ thấy khó cạnh tranh với những siêu thị lớn."},{"en":"Over fifty students competed for just three scholarships.","vi":"Hơn năm mươi sinh viên cạnh tranh để giành chỉ ba suất học bổng."},{"en":"My brother will compete in the city swimming race next month.","vi":"Anh trai tôi sẽ thi đấu trong cuộc thi bơi của thành phố vào tháng tới."}]', '[{"phrase":"compete with"},{"phrase":"compete for"},{"phrase":"compete in"},{"phrase":"compete against"}]', 'compete with/against sb; compete for sth', '/kəmˈpiːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compe/compete__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 3, 'poll', 'cuộc thăm dò ý kiến', 'noun', '[{"en":"A recent poll shows that most people want more parks.","vi":"Một cuộc thăm dò gần đây cho thấy phần lớn mọi người muốn có thêm công viên."},{"en":"We ran a quick poll to choose the date for the party.","vi":"Chúng tôi đã làm một cuộc thăm dò nhanh để chọn ngày tổ chức bữa tiệc."},{"en":"According to the poll, young people read fewer books than before.","vi":"Theo cuộc thăm dò, người trẻ đọc ít sách hơn trước."}]', '[{"phrase":"opinion poll"},{"phrase":"recent poll"},{"phrase":"conduct a poll"},{"phrase":"according to the poll"}]', NULL, '/pəʊl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pol/poll_/poll__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 4, 'weak', 'yếu; kém', 'adjective', '[{"en":"I still felt weak after being sick for a week.","vi":"Tôi vẫn thấy yếu sau khi bị ốm một tuần."},{"en":"Math has always been my weakest subject at school.","vi":"Toán luôn là môn yếu nhất của tôi ở trường."},{"en":"The signal is too weak to make a video call here.","vi":"Ở đây tín hiệu quá yếu để gọi video."}]', '[{"phrase":"feel weak"},{"phrase":"weak point"},{"phrase":"weak signal"}]', NULL, '/wiːk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wea/weak_/weak__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 5, 'faith', 'niềm tin; sự tin tưởng', 'noun', '[{"en":"I have complete faith in my doctor''s advice.","vi":"Tôi hoàn toàn tin tưởng lời khuyên của bác sĩ."},{"en":"Don''t lose faith; you will find a job soon.","vi":"Đừng mất niềm tin; bạn sẽ sớm tìm được việc thôi."},{"en":"Her parents always had faith that she would succeed.","vi":"Bố mẹ cô ấy luôn tin rằng cô ấy sẽ thành công."}]', '[{"phrase":"have faith in"},{"phrase":"lose faith"},{"phrase":"complete faith"}]', 'have faith in sb/sth: tin tưởng vào ai/điều gì', '/feɪθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fai/faith/faith__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 6, 'reduction', 'sự giảm; mức giảm', 'noun', '[{"en":"The new rules led to a big reduction in traffic accidents.","vi":"Các quy định mới đã giúp giảm mạnh số vụ tai nạn giao thông."},{"en":"Customers can get a ten percent price reduction this week.","vi":"Tuần này khách hàng được giảm giá mười phần trăm."},{"en":"We are hoping for a reduction in our electricity bill.","vi":"Chúng tôi đang hy vọng hóa đơn tiền điện sẽ giảm."}]', '[{"phrase":"reduction in"},{"phrase":"price reduction"},{"phrase":"significant reduction"},{"phrase":"cost reduction"}]', 'a reduction in sth: sự giảm về cái gì', '/rɪˈdʌkʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/red/reduc/reduction__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 7, 'reserve', 'đặt trước; dành riêng', 'verb', '[{"en":"I''ve reserved a table for four at seven o''clock.","vi":"Tôi đã đặt trước một bàn cho bốn người lúc bảy giờ."},{"en":"These front seats are reserved for elderly passengers.","vi":"Những ghế phía trước này dành riêng cho hành khách lớn tuổi."},{"en":"You should reserve your hotel room early during the holidays.","vi":"Bạn nên đặt phòng khách sạn sớm vào dịp lễ."}]', '[{"phrase":"reserve a table"},{"phrase":"reserve a room"},{"phrase":"reserved for"},{"phrase":"reserve the right"}]', NULL, '/rɪˈzɜːrv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/reser/reserve__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 8, 'complaint', 'lời phàn nàn; đơn khiếu nại', 'noun', '[{"en":"The hotel received many complaints about the noisy air conditioning.","vi":"Khách sạn nhận được nhiều lời phàn nàn về máy lạnh ồn ào."},{"en":"I would like to make a complaint about the service.","vi":"Tôi muốn khiếu nại về chất lượng phục vụ."},{"en":"If you have any complaints, please call our customer service team.","vi":"Nếu bạn có bất kỳ phàn nàn nào, vui lòng gọi cho bộ phận chăm sóc khách hàng."}]', '[{"phrase":"make a complaint"},{"phrase":"complaints about"},{"phrase":"receive a complaint"},{"phrase":"file a complaint"}]', NULL, '/kəmˈpleɪnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compl/complaint__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 9, 'bore', 'làm chán', 'verb', '[{"en":"I won''t bore you with all the details of my trip.","vi":"Mình sẽ không làm bạn chán với đủ thứ chi tiết về chuyến đi đâu."},{"en":"Long meetings always bore me to death.","vi":"Những cuộc họp dài lúc nào cũng làm tôi chán muốn chết."},{"en":"Did the movie bore the kids, or did they enjoy it?","vi":"Bộ phim có làm bọn trẻ thấy chán không, hay chúng thích nó?"}]', '[{"phrase":"bore you with"},{"phrase":"bore me to death"},{"phrase":"bore someone to tears"}]', 'bored (thấy chán) ≠ boring (gây chán)', '/bɔːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bor/bore_/bore__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 10, 'mission', 'nhiệm vụ; sứ mệnh', 'noun', '[{"en":"The rescue mission lasted two days in heavy rain.","vi":"Nhiệm vụ cứu hộ kéo dài hai ngày dưới mưa lớn."},{"en":"Our company''s mission is to make healthy food affordable.","vi":"Sứ mệnh của công ty chúng tôi là làm cho thực phẩm lành mạnh có giá phải chăng."},{"en":"My mission today is to clean the whole garage.","vi":"Nhiệm vụ của tôi hôm nay là dọn sạch cả nhà để xe."}]', '[{"phrase":"rescue mission"},{"phrase":"mission statement"},{"phrase":"on a mission"},{"phrase":"complete a mission"}]', NULL, '/ˈmɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mis/missi/mission__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 11, 'somehow', 'bằng cách nào đó; không hiểu sao', 'adverb', '[{"en":"She somehow managed to finish the project on time.","vi":"Bằng cách nào đó cô ấy đã xoay xở hoàn thành dự án đúng hạn."},{"en":"I left early, but somehow I still missed the bus.","vi":"Tôi đã đi sớm, nhưng không hiểu sao vẫn lỡ chuyến xe buýt."},{"en":"The house felt different somehow after the kids moved out.","vi":"Không hiểu sao căn nhà có cảm giác khác đi sau khi bọn trẻ dọn ra ở riêng."}]', '[{"phrase":"somehow managed to"},{"phrase":"but somehow"},{"phrase":"somehow or other"}]', NULL, '/ˈsʌmhaʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/som/someh/somehow__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 12, 'tone', 'giọng điệu; tông màu', 'noun', '[{"en":"I didn''t like the angry tone of his email.","vi":"Tôi không thích giọng điệu giận dữ trong email của anh ấy."},{"en":"Please don''t use that tone of voice with me.","vi":"Làm ơn đừng nói với tôi bằng giọng điệu đó."},{"en":"We painted the bedroom in soft, warm tones.","vi":"Chúng tôi sơn phòng ngủ bằng những tông màu ấm và dịu."}]', '[{"phrase":"tone of voice"},{"phrase":"angry tone"},{"phrase":"friendly tone"},{"phrase":"set the tone"}]', NULL, '/təʊn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ton/tone_/tone__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 13, 'neighborhood', 'khu phố; khu dân cư', 'noun', '[{"en":"We live in a quiet neighborhood near the river.","vi":"Chúng tôi sống ở một khu phố yên tĩnh gần con sông."},{"en":"There are three good restaurants in my neighborhood.","vi":"Khu tôi ở có ba nhà hàng ngon."},{"en":"The whole neighborhood came out to help after the storm.","vi":"Cả khu phố đã ra giúp đỡ sau cơn bão."}]', '[{"phrase":"quiet neighborhood"},{"phrase":"in my neighborhood"},{"phrase":"safe neighborhood"},{"phrase":"whole neighborhood"}]', 'Anh: neighbourhood · Mỹ: neighborhood', '/ˈneɪbərˌhʊd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 14, 'passenger', 'hành khách', 'noun', '[{"en":"All passengers must wear seat belts during the flight.","vi":"Tất cả hành khách phải thắt dây an toàn trong suốt chuyến bay."},{"en":"The bus was full, so some passengers had to stand.","vi":"Xe buýt đã đầy nên một số hành khách phải đứng."},{"en":"My sister sat in the passenger seat and read the map.","vi":"Chị tôi ngồi ở ghế phụ và xem bản đồ."}]', '[{"phrase":"passenger seat"},{"phrase":"bus passengers"},{"phrase":"passenger train"},{"phrase":"airline passengers"}]', NULL, '/ˈpæsɪndʒər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pas/passe/passenger__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 15, 'justice', 'công lý; sự công bằng', 'noun', '[{"en":"The court''s decision was a victory for justice.","vi":"Phán quyết của tòa án là một chiến thắng của công lý."},{"en":"Children have a strong sense of justice and hate unfair rules.","vi":"Trẻ em có ý thức mạnh mẽ về sự công bằng và ghét những quy định bất công."},{"en":"The family finally got justice after a long legal fight.","vi":"Cuối cùng gia đình ấy cũng đòi được công lý sau một cuộc chiến pháp lý dài."}]', '[{"phrase":"sense of justice"},{"phrase":"social justice"},{"phrase":"get justice"},{"phrase":"bring to justice"}]', 'không đếm được', '/ˈdʒʌstɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jus/justi/justice__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 16, 'phase', 'giai đoạn', 'noun', '[{"en":"The first phase of the project will finish in March.","vi":"Giai đoạn đầu của dự án sẽ hoàn thành vào tháng Ba."},{"en":"Many teenagers go through a phase of wanting to be alone.","vi":"Nhiều thanh thiếu niên trải qua một giai đoạn chỉ muốn ở một mình."},{"en":"Our city is entering a new phase of development.","vi":"Thành phố của chúng tôi đang bước vào một giai đoạn phát triển mới."}]', '[{"phrase":"first phase"},{"phrase":"new phase"},{"phrase":"final phase"},{"phrase":"go through a phase"}]', NULL, '/feɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pha/phase/phase__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 17, 'thin', 'mỏng; gầy', 'adjective', '[{"en":"Cut the tomatoes into thin slices for the sandwich.","vi":"Hãy cắt cà chua thành những lát mỏng để làm bánh mì kẹp."},{"en":"He looked very thin after his long illness.","vi":"Anh ấy trông rất gầy sau trận ốm dài."},{"en":"This jacket is too thin for winter in the mountains.","vi":"Chiếc áo khoác này quá mỏng để mặc mùa đông trên núi."}]', '[{"phrase":"thin slices"},{"phrase":"thin layer"},{"phrase":"tall and thin"},{"phrase":"very thin"}]', NULL, '/θɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thi/thin_/thin__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 18, 'rush', 'vội vàng; lao đi', 'verb', '[{"en":"Don''t rush; we still have plenty of time.","vi":"Đừng vội; chúng ta vẫn còn nhiều thời gian."},{"en":"She rushed to the hospital when she heard the news.","vi":"Cô ấy vội vã chạy đến bệnh viện khi nghe tin."},{"en":"I had to rush my lunch to get back to work.","vi":"Tôi phải ăn trưa vội vàng để kịp quay lại làm việc."}]', '[{"phrase":"rush to"},{"phrase":"rush into"},{"phrase":"rush out"},{"phrase":"rush hour"}]', NULL, '/rʌʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rus/rush_/rush__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 19, 'formal', 'trang trọng; chính thức', 'adjective', '[{"en":"You should wear formal clothes to the wedding dinner.","vi":"Bạn nên mặc trang phục trang trọng khi đến dự tiệc cưới."},{"en":"Use formal language when you write to your manager.","vi":"Hãy dùng ngôn ngữ trang trọng khi viết thư cho quản lý của bạn."},{"en":"We haven''t received a formal offer from the company yet.","vi":"Chúng tôi vẫn chưa nhận được lời mời làm việc chính thức từ công ty."}]', '[{"phrase":"formal clothes"},{"phrase":"formal language"},{"phrase":"formal offer"},{"phrase":"formal education"}]', 'formal ≠ informal (thân mật, không trang trọng)', '/ˈfɔːrml/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forma/formal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 20, 'religion', 'tôn giáo', 'noun', '[{"en":"The course teaches students about different cultures and religions.","vi":"Khóa học dạy sinh viên về các nền văn hóa và tôn giáo khác nhau."},{"en":"The role of religion in daily life differs from country to country.","vi":"Vai trò của tôn giáo trong đời sống hằng ngày khác nhau giữa các quốc gia."},{"en":"At work, we try not to talk about politics or religion.","vi":"Ở chỗ làm, chúng tôi cố không nói chuyện chính trị hay tôn giáo."}]', '[{"phrase":"role of religion"},{"phrase":"freedom of religion"},{"phrase":"world religions"}]', NULL, '/rɪˈlɪdʒən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relig/religion__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 21, 'employer', 'chủ lao động; nhà tuyển dụng', 'noun', '[{"en":"My employer pays for my English classes after work.","vi":"Công ty tôi làm trả tiền cho các lớp tiếng Anh sau giờ làm của tôi."},{"en":"Employers often look for people with good communication skills.","vi":"Nhà tuyển dụng thường tìm những người có kỹ năng giao tiếp tốt."},{"en":"The hospital is the largest employer in our town.","vi":"Bệnh viện là nơi sử dụng nhiều lao động nhất ở thị trấn chúng tôi."}]', '[{"phrase":"largest employer"},{"phrase":"former employer"},{"phrase":"potential employer"}]', 'employer (chủ) ≠ employee (nhân viên)', '/ɪmˈplɔɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emp/emplo/employer__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 22, 'reject', 'từ chối; bác bỏ', 'verb', '[{"en":"The bank rejected my application for a loan last month.","vi":"Tháng trước ngân hàng đã từ chối đơn xin vay của tôi."},{"en":"She rejected his offer to drive her home.","vi":"Cô ấy từ chối lời đề nghị chở cô về nhà của anh ta."},{"en":"The manager rejected the idea because it cost too much.","vi":"Quản lý bác bỏ ý tưởng đó vì nó quá tốn kém."}]', '[{"phrase":"reject an offer"},{"phrase":"reject an idea"},{"phrase":"reject an application"},{"phrase":"reject a proposal"}]', NULL, '/rɪˈdʒekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rej/rejec/reject__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 23, 'latter', 'cái sau; người sau', 'noun', '[{"en":"We could take the bus or the train, but I prefer the latter.","vi":"Chúng ta có thể đi xe buýt hoặc tàu hỏa, nhưng tôi thích đi tàu hơn."},{"en":"My uncle and aunt both applied, but only the latter got the job.","vi":"Chú và cô tôi đều nộp đơn, nhưng chỉ có cô tôi được nhận."},{"en":"Between cats and dogs, most children in my class choose the latter.","vi":"Giữa mèo và chó, hầu hết trẻ em trong lớp tôi chọn chó."}]', '[{"phrase":"the latter"},{"phrase":"the former and the latter"},{"phrase":"the latter half"}]', 'the former (cái trước) ≠ the latter (cái sau)', '/ˈlætər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lat/latte/latter__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 24, 'plate', 'cái đĩa', 'noun', '[{"en":"Could you put the plates on the table, please?","vi":"Bạn đặt đĩa lên bàn giúp mình được không?"},{"en":"I''d like a plate of fried rice, please.","vi":"Cho tôi một đĩa cơm chiên nhé."},{"en":"Please wash your plate when you finish eating.","vi":"Ăn xong thì vui lòng rửa đĩa của bạn."}]', '[{"phrase":"a plate of"},{"phrase":"dinner plate"},{"phrase":"paper plate"},{"phrase":"clean plate"}]', NULL, '/pleɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/plate/plate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 25, 'ban', 'cấm', 'verb', '[{"en":"Smoking is banned in all restaurants in the city.","vi":"Hút thuốc bị cấm ở tất cả nhà hàng trong thành phố."},{"en":"The school banned phones in classrooms last year.","vi":"Năm ngoái nhà trường đã cấm dùng điện thoại trong lớp học."},{"en":"He was banned from driving for six months.","vi":"Anh ta bị cấm lái xe trong sáu tháng."}]', '[{"phrase":"banned from"},{"phrase":"ban smoking"},{"phrase":"completely ban"}]', 'ban – banned – banned; be banned from doing sth', '/bæn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/ban/ban__/ban__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 26, 'steal', 'ăn cắp; lấy trộm', 'verb', '[{"en":"Someone stole my bike from outside the library.","vi":"Có ai đó đã lấy trộm xe đạp của tôi ở bên ngoài thư viện."},{"en":"Keep your bag close because thieves often steal from tourists.","vi":"Hãy giữ túi sát người vì kẻ trộm thường ăn cắp đồ của khách du lịch."},{"en":"He was caught stealing money from the shop.","vi":"Anh ta bị bắt quả tang ăn cắp tiền của cửa hàng."}]', '[{"phrase":"steal money"},{"phrase":"steal from"},{"phrase":"steal a car"}]', 'steal – stole – stolen', '/stiːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ste/steal/steal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 27, 'protest', 'cuộc biểu tình; sự phản đối', 'noun', '[{"en":"Parents held a protest outside the school about the new fees.","vi":"Phụ huynh đã tổ chức một cuộc biểu tình trước cổng trường để phản đối khoản phí mới."},{"en":"Several customers left the shop in protest.","vi":"Vài khách hàng đã bỏ ra khỏi cửa hàng để phản đối."},{"en":"The plan went ahead despite strong protests from local residents.","vi":"Kế hoạch vẫn được tiến hành bất chấp sự phản đối mạnh mẽ của người dân địa phương."}]', '[{"phrase":"in protest"},{"phrase":"hold a protest"},{"phrase":"strong protest"},{"phrase":"protest against"}]', NULL, '/ˈprəʊtest/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prote/protest__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 28, 'index', 'bảng tra cứu; chỉ số', 'noun', '[{"en":"Check the index at the back of the book for that topic.","vi":"Hãy xem bảng tra cứu ở cuối sách để tìm chủ đề đó."},{"en":"The price index rose by two percent last month.","vi":"Chỉ số giá đã tăng hai phần trăm vào tháng trước."},{"en":"The book has a detailed index, so finding recipes is easy.","vi":"Cuốn sách có bảng tra cứu chi tiết nên tìm công thức nấu ăn rất dễ."}]', '[{"phrase":"price index"},{"phrase":"detailed index"},{"phrase":"index card"}]', 'số nhiều: indexes hoặc indices', '/ˈɪndeks/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/index/index__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 29, 'sad', 'buồn', 'adjective', '[{"en":"I felt sad when my best friend moved away.","vi":"Tôi thấy buồn khi bạn thân của tôi chuyển đi nơi khác."},{"en":"It''s sad that the old cinema is closing down.","vi":"Thật đáng buồn khi rạp chiếu phim cũ sắp đóng cửa."},{"en":"She watched a sad movie and cried at the end.","vi":"Cô ấy xem một bộ phim buồn và khóc ở đoạn cuối."}]', '[{"phrase":"feel sad"},{"phrase":"sad movie"},{"phrase":"sad news"},{"phrase":"look sad"}]', NULL, '/sæd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sad/sad__/sad__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-07', 30, 'frequently', 'thường xuyên', 'adverb', '[{"en":"Buses run frequently between the airport and the city center.","vi":"Xe buýt chạy thường xuyên giữa sân bay và trung tâm thành phố."},{"en":"I frequently forget where I left my glasses.","vi":"Tôi thường xuyên quên mình để kính ở đâu."},{"en":"This is one of our most frequently asked questions.","vi":"Đây là một trong những câu hỏi thường gặp nhất của chúng tôi."}]', '[{"phrase":"frequently asked questions"},{"phrase":"run frequently"},{"phrase":"frequently used"}]', NULL, '/ˈfriːkwəntli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fre/frequ/frequently__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-4-08', 'ngsl-4', 'Thông dụng 1.501–2.000 · Bộ 8', 'New General Service List, thứ hạng 1.501–2.000', '#3da9fc', 'BookOpen', 8);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 1, 'circle', 'hình tròn; vòng tròn; nhóm (bạn bè)', 'noun', '[{"en":"The teacher asked the children to sit in a circle.","vi":"Cô giáo bảo các em ngồi thành vòng tròn."},{"en":"Draw a circle around the correct answer.","vi":"Hãy khoanh tròn đáp án đúng."},{"en":"She has a small circle of close friends.","vi":"Cô ấy có một nhóm nhỏ bạn thân."}]', '[{"phrase":"draw a circle"},{"phrase":"sit in a circle"},{"phrase":"circle of friends"}]', NULL, '/ˈsɜːrkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cir/circl/circle__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 2, 'helpful', 'hữu ích; sẵn lòng giúp đỡ', 'adjective', '[{"en":"Thanks for your advice, it was really helpful.","vi":"Cảm ơn lời khuyên của bạn, nó thật sự rất hữu ích."},{"en":"The staff at the hotel were friendly and helpful.","vi":"Nhân viên khách sạn thân thiện và nhiệt tình giúp đỡ."},{"en":"It might be helpful to write down your questions before the meeting.","vi":"Viết ra các câu hỏi trước buổi họp có thể sẽ hữu ích."}]', '[{"phrase":"very helpful"},{"phrase":"helpful advice"},{"phrase":"helpful staff"}]', NULL, '/ˈhelpfl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hel/helpf/helpful__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 3, 'command', 'mệnh lệnh; lệnh (máy tính); sự thành thạo', 'noun', '[{"en":"The soldiers waited for the command to move forward.","vi":"Những người lính chờ lệnh tiến lên."},{"en":"Type this command to restart the program.","vi":"Hãy gõ lệnh này để khởi động lại chương trình."},{"en":"After two years abroad, she has a good command of English.","vi":"Sau hai năm ở nước ngoài, cô ấy sử dụng tiếng Anh thành thạo."}]', '[{"phrase":"give a command"},{"phrase":"follow a command"},{"phrase":"command of English"}]', 'have a good command of + ngôn ngữ = thành thạo', '/kəˈmænd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/comma/command__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 4, 'attractive', 'hấp dẫn; thu hút; ưa nhìn', 'adjective', '[{"en":"He thinks she is the most attractive woman in the room.","vi":"Anh ấy nghĩ cô ấy là người phụ nữ cuốn hút nhất trong phòng."},{"en":"The company offered me a very attractive salary.","vi":"Công ty đã đề nghị cho tôi một mức lương rất hấp dẫn."},{"en":"Low prices make the city attractive to young travelers.","vi":"Giá cả thấp khiến thành phố này hấp dẫn với du khách trẻ."}]', '[{"phrase":"attractive offer"},{"phrase":"attractive to"},{"phrase":"highly attractive"},{"phrase":"physically attractive"}]', NULL, '/əˈtræktɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attra/attractive__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 5, 'sick', 'ốm, bệnh; buồn nôn; chán ngấy', 'adjective', '[{"en":"I can''t come to work today because I''m sick.","vi":"Hôm nay tôi không đi làm được vì tôi bị ốm."},{"en":"Reading in the car always makes me feel sick.","vi":"Đọc sách trên ô tô lúc nào cũng làm tôi buồn nôn."},{"en":"I''m sick of eating noodles every night.","vi":"Tôi chán ngấy việc tối nào cũng ăn mì rồi."}]', '[{"phrase":"feel sick"},{"phrase":"get sick"},{"phrase":"sick of"},{"phrase":"call in sick"}]', 'be sick of sth = chán ngấy cái gì', '/sɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sic/sick_/sick__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 6, 'impression', 'ấn tượng; cảm tưởng', 'noun', '[{"en":"Wear something smart to make a good first impression.","vi":"Hãy mặc gì đó lịch sự để tạo ấn tượng tốt ban đầu."},{"en":"I got the impression that he didn''t like the idea.","vi":"Tôi có cảm giác là anh ấy không thích ý tưởng đó."},{"en":"What was your first impression of the new office?","vi":"Ấn tượng đầu tiên của bạn về văn phòng mới là gì?"}]', '[{"phrase":"make a good impression"},{"phrase":"first impression"},{"phrase":"get the impression"},{"phrase":"impression of"}]', NULL, '/ɪmˈpreʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impre/impression__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 7, 'unable', 'không thể; không có khả năng', 'adjective', '[{"en":"We were unable to find a hotel near the station.","vi":"Chúng tôi không thể tìm được khách sạn nào gần nhà ga."},{"en":"She was unable to sleep because of the noise.","vi":"Cô ấy không ngủ được vì tiếng ồn."},{"en":"I''m sorry, but the manager is unable to see you today.","vi":"Xin lỗi, hôm nay quản lý không thể gặp bạn được."}]', '[{"phrase":"unable to do"},{"phrase":"unable to find"},{"phrase":"unable to attend"}]', 'be unable to + V nguyên mẫu', '/ʌnˈeɪbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/una/unabl/unable__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 8, 'joke', 'chuyện cười; trò đùa', 'noun', '[{"en":"My dad told a joke and everyone laughed.","vi":"Bố tôi kể một chuyện cười và mọi người đều bật cười."},{"en":"Don''t be angry, it was only a joke.","vi":"Đừng giận, đó chỉ là một trò đùa thôi."},{"en":"I didn''t get the joke, so could you explain it?","vi":"Tôi không hiểu câu đùa, bạn giải thích được không?"}]', '[{"phrase":"tell a joke"},{"phrase":"just a joke"},{"phrase":"get the joke"},{"phrase":"make a joke"}]', NULL, '/dʒəʊk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jok/joke_/joke__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 9, 'sky', 'bầu trời', 'noun', '[{"en":"There wasn''t a single cloud in the sky this morning.","vi":"Sáng nay trên bầu trời không có lấy một gợn mây."},{"en":"The sky turned dark just before the storm.","vi":"Bầu trời tối sầm lại ngay trước cơn bão."},{"en":"We lay on the grass and looked up at the night sky.","vi":"Chúng tôi nằm trên bãi cỏ và ngắm nhìn bầu trời đêm."}]', '[{"phrase":"blue sky"},{"phrase":"clear sky"},{"phrase":"night sky"},{"phrase":"in the sky"}]', NULL, '/skaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sky/sky__/sky__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 10, 'column', 'cột (trong bảng); cột trụ; chuyên mục (báo)', 'noun', '[{"en":"Write the prices in the second column of the table.","vi":"Hãy ghi giá vào cột thứ hai của bảng."},{"en":"The old building has tall stone columns at the front.","vi":"Tòa nhà cũ có những cột đá cao ở mặt trước."},{"en":"She writes a weekly column about food for a local newspaper.","vi":"Cô ấy viết một chuyên mục ẩm thực hằng tuần cho một tờ báo địa phương."}]', '[{"phrase":"first column"},{"phrase":"stone column"},{"phrase":"weekly column"},{"phrase":"newspaper column"}]', NULL, '/ˈkɑːləm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/col/colum/column__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 11, 'electronic', '(thuộc) điện tử', 'adjective', '[{"en":"Please turn off all electronic devices during the flight.","vi":"Vui lòng tắt tất cả thiết bị điện tử trong suốt chuyến bay."},{"en":"You can pay the bill by electronic transfer.","vi":"Bạn có thể thanh toán hóa đơn bằng chuyển khoản điện tử."},{"en":"The library now keeps most of its records in electronic form.","vi":"Thư viện hiện lưu phần lớn hồ sơ dưới dạng điện tử."}]', '[{"phrase":"electronic device"},{"phrase":"electronic equipment"},{"phrase":"electronic form"}]', 'electronic (adj) ≠ electronics (n): ngành/đồ điện tử', '/ɪˌlekˈtrɑːnɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ele/elect/electronic__us_5.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 12, 'impose', 'áp đặt; áp (thuế, phạt, lệnh cấm)', 'verb', '[{"en":"The city has imposed a ban on smoking in parks.","vi":"Thành phố đã áp lệnh cấm hút thuốc trong công viên."},{"en":"Parents shouldn''t impose their own dreams on their children.","vi":"Cha mẹ không nên áp đặt ước mơ của mình lên con cái."},{"en":"The government plans to impose a new tax on sugary drinks.","vi":"Chính phủ dự định áp một loại thuế mới lên đồ uống có đường."}]', '[{"phrase":"impose a ban"},{"phrase":"impose a tax"},{"phrase":"impose a fine"},{"phrase":"impose on"}]', 'impose sth on sb/sth', '/ɪmˈpəʊz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impos/impose__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 13, 'criminal', 'tội phạm; kẻ phạm tội', 'noun', '[{"en":"The police are still looking for the criminals who robbed the bank.","vi":"Cảnh sát vẫn đang truy tìm những tên tội phạm đã cướp ngân hàng."},{"en":"He was treated like a criminal for a small mistake.","vi":"Anh ấy bị đối xử như tội phạm chỉ vì một lỗi nhỏ."},{"en":"Dangerous criminals are kept in this prison.","vi":"Những tội phạm nguy hiểm bị giam ở nhà tù này."}]', '[{"phrase":"dangerous criminal"},{"phrase":"convicted criminal"},{"phrase":"catch a criminal"}]', 'Cũng là tính từ: criminal record = tiền án', '/ˈkrɪmɪnl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cri/crimi/criminal__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 14, 'besides', 'ngoài ra; bên cạnh; hơn nữa', 'preposition', '[{"en":"Besides English, she can also speak French and Japanese.","vi":"Ngoài tiếng Anh, cô ấy còn nói được tiếng Pháp và tiếng Nhật."},{"en":"Who else was at the party besides your cousins?","vi":"Ngoài anh chị em họ của bạn ra, còn ai ở bữa tiệc nữa?"},{"en":"I don''t want to go out tonight, and besides, it''s raining.","vi":"Tối nay tôi không muốn ra ngoài, hơn nữa trời đang mưa."}]', '[{"phrase":"besides that"},{"phrase":"anyone besides"},{"phrase":"and besides"}]', 'besides (ngoài ra) ≠ beside (bên cạnh, về vị trí)', '/bɪˈsaɪdz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bes/besid/besides__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 15, 'properly', 'đúng cách; cẩn thận, tử tế', 'adverb', '[{"en":"Make sure the door is properly locked before you leave.","vi":"Hãy chắc chắn cửa đã được khóa cẩn thận trước khi bạn đi."},{"en":"My laptop hasn''t been working properly since I dropped it.","vi":"Từ hôm tôi làm rơi, máy tính xách tay không chạy bình thường nữa."},{"en":"I was so worried that I couldn''t eat properly for days.","vi":"Tôi lo đến mức mấy ngày liền không ăn uống tử tế được."}]', '[{"phrase":"work properly"},{"phrase":"properly trained"},{"phrase":"eat properly"},{"phrase":"done properly"}]', NULL, '/ˈprɑːpərli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prope/properly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 16, 'ancient', 'cổ xưa; cổ đại', 'adjective', '[{"en":"We visited an ancient temple on our trip last summer.","vi":"Chúng tôi đã đến thăm một ngôi đền cổ trong chuyến đi hè năm ngoái."},{"en":"My son loves reading stories about ancient Egypt.","vi":"Con trai tôi rất thích đọc truyện về Ai Cập cổ đại."},{"en":"People have used this ancient road for thousands of years.","vi":"Con người đã dùng con đường cổ này suốt hàng nghìn năm."}]', '[{"phrase":"ancient history"},{"phrase":"ancient times"},{"phrase":"ancient city"},{"phrase":"ancient Greece"}]', NULL, '/ˈeɪnʃənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/anc/ancie/ancient__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 17, 'coast', 'bờ biển; vùng ven biển', 'noun', '[{"en":"We spent a week driving along the coast.","vi":"Chúng tôi dành một tuần lái xe dọc bờ biển."},{"en":"My grandparents live in a small town on the east coast.","vi":"Ông bà tôi sống ở một thị trấn nhỏ trên bờ biển phía đông."},{"en":"The storm is expected to hit the coast tomorrow night.","vi":"Cơn bão dự kiến sẽ đổ bộ vào bờ biển tối mai."}]', '[{"phrase":"along the coast"},{"phrase":"on the coast"},{"phrase":"east coast"},{"phrase":"off the coast"}]', NULL, '/kəʊst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coa/coast/coast__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 18, 'ill', 'ốm, bệnh', 'adjective', '[{"en":"She stayed home from school because she was ill.","vi":"Cô bé nghỉ học ở nhà vì bị ốm."},{"en":"My grandfather has been seriously ill for several months.","vi":"Ông tôi đã bị bệnh nặng mấy tháng nay."},{"en":"I felt ill after eating the seafood last night.","vi":"Tôi thấy khó chịu trong người sau khi ăn hải sản tối qua."}]', '[{"phrase":"seriously ill"},{"phrase":"fall ill"},{"phrase":"feel ill"},{"phrase":"mentally ill"}]', 'ill thường đứng sau động từ (be/feel ill); trước danh từ dùng sick: a sick child', '/ɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ill/ill__/ill__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 19, 'kick', 'đá', 'verb', '[{"en":"The boy kicked the ball over the fence.","vi":"Cậu bé đá quả bóng bay qua hàng rào."},{"en":"Stop kicking the back of my seat, please.","vi":"Làm ơn đừng đá vào lưng ghế của tôi nữa."},{"en":"The horse kicked him when he walked behind it.","vi":"Con ngựa đá anh ấy khi anh ấy đi phía sau nó."}]', '[{"phrase":"kick a ball"},{"phrase":"kick the door"},{"phrase":"kick off"}]', NULL, '/kɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kic/kick_/kick__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 20, 'closely', 'chặt chẽ; sát sao; kỹ lưỡng', 'adverb', '[{"en":"Our team works closely with the design department.","vi":"Nhóm chúng tôi làm việc chặt chẽ với phòng thiết kế."},{"en":"If you look closely, you can see a small crack.","vi":"Nếu nhìn kỹ, bạn có thể thấy một vết nứt nhỏ."},{"en":"The doctors are watching his condition closely after the surgery.","vi":"Các bác sĩ đang theo dõi sát sao tình trạng của anh ấy sau ca phẫu thuật."}]', '[{"phrase":"work closely with"},{"phrase":"look closely"},{"phrase":"watch closely"},{"phrase":"closely related"}]', NULL, '/ˈkləʊsli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/clo/close/closely__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 21, 'multiple', 'nhiều; đa dạng', 'adjective', '[{"en":"The test has twenty multiple choice questions.","vi":"Bài kiểm tra có hai mươi câu hỏi trắc nghiệm."},{"en":"I''ve tried calling her multiple times, but she never answers.","vi":"Tôi đã gọi cho cô ấy nhiều lần nhưng cô ấy không bao giờ nghe máy."},{"en":"You can open multiple windows on the screen at once.","vi":"Bạn có thể mở nhiều cửa sổ trên màn hình cùng lúc."}]', '[{"phrase":"multiple times"},{"phrase":"multiple choice"},{"phrase":"multiple copies"}]', 'multiple choice = trắc nghiệm', '/ˈmʌltɪpl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mul/multi/multiple__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 22, 'yield', 'mang lại, sinh ra; nhường (đường)', 'verb', '[{"en":"Our search yielded some useful information about the house.","vi":"Cuộc tìm kiếm của chúng tôi đã mang lại vài thông tin hữu ích về ngôi nhà."},{"en":"These trees yield a lot of fruit every summer.","vi":"Mấy cây này cho rất nhiều quả vào mỗi mùa hè."},{"en":"Drivers must yield to people crossing the street.","vi":"Tài xế phải nhường đường cho người đi bộ qua đường."}]', '[{"phrase":"yield results"},{"phrase":"yield information"},{"phrase":"yield to"}]', 'Danh từ: yield = sản lượng, lợi suất', '/jiːld/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/y/yie/yield/yield__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 23, 'via', 'qua, thông qua; đi qua (nơi nào)', 'preposition', '[{"en":"We flew to London via Dubai because it was much cheaper.","vi":"Chúng tôi bay đến Luân Đôn qua Dubai vì rẻ hơn nhiều."},{"en":"I''ll send you the photos via email tonight.","vi":"Tối nay tôi sẽ gửi ảnh cho bạn qua email."},{"en":"Students can join the class via video call if they are sick.","vi":"Học sinh có thể tham gia lớp học qua gọi video nếu bị ốm."}]', '[{"phrase":"via email"},{"phrase":"via the internet"},{"phrase":"via satellite"}]', NULL, '/ˈvaɪə/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/via/via__/via__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 24, 'legislation', 'luật pháp; việc lập pháp', 'noun', '[{"en":"New legislation will make it illegal to use a phone while driving.","vi":"Luật mới sẽ khiến việc dùng điện thoại khi lái xe trở thành phạm pháp."},{"en":"The country has strict legislation to protect the environment.","vi":"Đất nước này có luật pháp nghiêm ngặt để bảo vệ môi trường."},{"en":"Many workers support the legislation on a higher minimum wage.","vi":"Nhiều người lao động ủng hộ luật về mức lương tối thiểu cao hơn."}]', '[{"phrase":"new legislation"},{"phrase":"introduce legislation"},{"phrase":"pass legislation"},{"phrase":"legislation on"}]', 'không đếm được', '/ˌledʒɪsˈleɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/leg/legis/legislation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 25, 'county', 'hạt (đơn vị hành chính ở Anh, Mỹ); quận, huyện', 'noun', '[{"en":"My aunt works as a nurse at the county hospital.","vi":"Dì tôi làm y tá ở bệnh viện của hạt."},{"en":"It is one of the smallest counties in the state.","vi":"Đó là một trong những hạt nhỏ nhất của bang."},{"en":"Farmers from across the county bring their animals to the fair.","vi":"Nông dân khắp hạt mang vật nuôi của mình đến hội chợ."}]', '[{"phrase":"county council"},{"phrase":"county hospital"},{"phrase":"county fair"},{"phrase":"across the county"}]', NULL, '/ˈkaʊnti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/count/county__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 26, 'unlike', 'không giống; khác với', 'preposition', '[{"en":"Unlike his older brother, my husband really enjoys cooking.","vi":"Không giống anh trai mình, chồng tôi rất thích nấu ăn."},{"en":"The weather here is unlike anything I''ve experienced before.","vi":"Thời tiết ở đây khác hẳn mọi thứ tôi từng trải qua."},{"en":"It''s unlike her to be late, so I''m a little worried.","vi":"Cô ấy vốn không hay đến muộn, nên tôi hơi lo."}]', '[{"phrase":"unlike most"},{"phrase":"unlike anything"},{"phrase":"quite unlike"}]', 'It''s unlike sb to do sth = không giống tính ai khi làm gì', '/ˌʌnˈlaɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/unl/unlik/unlike__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 27, 'mobile', 'di động; lưu động; điện thoại di động', 'adjective', '[{"en":"Please turn your mobile phone to silent during the film.","vi":"Vui lòng để điện thoại di động ở chế độ im lặng trong khi xem phim."},{"en":"A mobile library visits our village every Tuesday.","vi":"Một thư viện lưu động đến làng chúng tôi vào mỗi thứ Ba."},{"en":"After the operation, she was mobile again within a week.","vi":"Sau ca phẫu thuật, cô ấy đi lại được trong vòng một tuần."}]', '[{"phrase":"mobile phone"},{"phrase":"mobile device"},{"phrase":"mobile app"}]', 'Anh: mobile (phone) · Mỹ: cell phone', '/ˈməʊbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mob/mobil/mobile__us_7.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 28, 'assistant', 'trợ lý; người phụ tá', 'noun', '[{"en":"My assistant will send you the details this afternoon.","vi":"Trợ lý của tôi sẽ gửi thông tin chi tiết cho bạn chiều nay."},{"en":"She works as a teaching assistant at a primary school.","vi":"Cô ấy làm trợ giảng ở một trường tiểu học."},{"en":"Ask the shop assistant if they have this shirt in blue.","vi":"Hãy hỏi nhân viên bán hàng xem họ có chiếc áo này màu xanh không."}]', '[{"phrase":"personal assistant"},{"phrase":"shop assistant"},{"phrase":"teaching assistant"},{"phrase":"research assistant"}]', NULL, '/əˈsɪstənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assis/assistant__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 29, 'implement', 'thực hiện; triển khai; thi hành', 'verb', '[{"en":"The school will implement the new rules next month.","vi":"Nhà trường sẽ áp dụng các quy định mới vào tháng tới."},{"en":"It took us two years to implement the plan.","vi":"Chúng tôi mất hai năm để thực hiện kế hoạch đó."},{"en":"The changes have not been implemented yet.","vi":"Những thay đổi này vẫn chưa được triển khai."}]', '[{"phrase":"implement a plan"},{"phrase":"implement changes"},{"phrase":"implement a policy"},{"phrase":"fully implement"}]', NULL, '/ˈɪmplɪment/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/imple/implement__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-08', 30, 'chart', 'biểu đồ; bảng xếp hạng (âm nhạc)', 'noun', '[{"en":"This chart shows how our sales have grown this year.","vi":"Biểu đồ này cho thấy doanh số của chúng ta đã tăng thế nào trong năm nay."},{"en":"Can you put these numbers into a simple chart?","vi":"Bạn có thể đưa những con số này vào một biểu đồ đơn giản không?"},{"en":"Their new song went straight to the top of the charts.","vi":"Bài hát mới của họ lập tức đứng đầu bảng xếp hạng."}]', '[{"phrase":"pie chart"},{"phrase":"bar chart"},{"phrase":"top of the charts"},{"phrase":"chart shows"}]', NULL, '/tʃɑːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chart/chart__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-4-11', 'ngsl-4', 'Thông dụng 1.501–2.000 · Bộ 11', 'New General Service List, thứ hạng 1.501–2.000', '#3da9fc', 'BookOpen', 11);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 1, 'vast', 'rộng lớn, bao la; rất nhiều, khổng lồ', 'adjective', '[{"en":"From the plane, we could see the vast ocean below us.","vi":"Từ trên máy bay, chúng tôi có thể nhìn thấy đại dương bao la bên dưới."},{"en":"The vast majority of students passed the final exam.","vi":"Phần lớn sinh viên đã vượt qua kỳ thi cuối kỳ."},{"en":"She spent a vast amount of money on her new house.","vi":"Cô ấy đã tiêu một số tiền khổng lồ cho ngôi nhà mới."}]', '[{"phrase":"vast majority"},{"phrase":"vast amount"},{"phrase":"vast area"}]', NULL, '/væst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vas/vast_/vast__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 2, 'exhibition', 'cuộc triển lãm; sự trưng bày', 'noun', '[{"en":"We went to a photo exhibition at the city museum.","vi":"Chúng tôi đã đi xem một cuộc triển lãm ảnh ở bảo tàng thành phố."},{"en":"The gallery is holding an exhibition of work by local artists.","vi":"Phòng tranh đang tổ chức một cuộc triển lãm tác phẩm của các nghệ sĩ địa phương."},{"en":"Did you see the science exhibition at school last week?","vi":"Bạn có xem triển lãm khoa học ở trường tuần trước không?"}]', '[{"phrase":"art exhibition"},{"phrase":"hold an exhibition"},{"phrase":"exhibition of"}]', NULL, '/ˌeksɪˈbɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exh/exhib/exhibition__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 3, 'producer', 'nhà sản xuất (phim, nhạc); nơi sản xuất', 'noun', '[{"en":"My uncle works as a TV producer in the capital.","vi":"Chú tôi làm nhà sản xuất chương trình truyền hình ở thủ đô."},{"en":"The film''s producer wanted a happier ending.","vi":"Nhà sản xuất của bộ phim muốn một cái kết vui hơn."},{"en":"This region is a major producer of rice and fruit.","vi":"Vùng này là nơi sản xuất lúa gạo và trái cây lớn."}]', '[{"phrase":"film producer"},{"phrase":"record producer"},{"phrase":"major producer"}]', NULL, '/prəˈduːsər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/produ/producer__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 4, 'regional', '(thuộc) vùng, khu vực', 'adjective', '[{"en":"She works in the company''s regional office in the north.","vi":"Cô ấy làm việc ở văn phòng khu vực phía bắc của công ty."},{"en":"Our team won the regional championship last year.","vi":"Đội chúng tôi đã vô địch giải khu vực năm ngoái."},{"en":"Each regional dish has its own special flavor.","vi":"Mỗi món ăn vùng miền đều có hương vị đặc trưng riêng."}]', '[{"phrase":"regional office"},{"phrase":"regional news"},{"phrase":"regional development"}]', NULL, '/ˈriːdʒənl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regio/regional__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 5, 'immediate', 'ngay lập tức; trước mắt; gần nhất, trực tiếp', 'adjective', '[{"en":"The new medicine had an immediate effect on her pain.","vi":"Thuốc mới có tác dụng giảm đau cho cô ấy ngay lập tức."},{"en":"We need an immediate answer, so please call us today.","vi":"Chúng tôi cần câu trả lời ngay, vì vậy vui lòng gọi cho chúng tôi hôm nay."},{"en":"Only my immediate family came to the small wedding.","vi":"Chỉ có gia đình ruột thịt của tôi đến dự đám cưới nhỏ."}]', '[{"phrase":"immediate effect"},{"phrase":"immediate action"},{"phrase":"immediate family"},{"phrase":"immediate future"}]', NULL, '/ɪˈmiːdiət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imm/immed/immediate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 6, 'incident', 'vụ việc; sự cố', 'noun', '[{"en":"Police are investigating an incident at the train station.","vi":"Cảnh sát đang điều tra một vụ việc ở nhà ga."},{"en":"Nobody was hurt in the incident, but the car was badly damaged.","vi":"Không ai bị thương trong vụ việc, nhưng chiếc xe bị hư hỏng nặng."},{"en":"Please report any serious incident to your manager right away.","vi":"Vui lòng báo ngay cho quản lý về bất kỳ sự cố nghiêm trọng nào."}]', '[{"phrase":"serious incident"},{"phrase":"report an incident"},{"phrase":"without incident"}]', NULL, '/ˈɪnsɪdənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incid/incident__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 7, 'childhood', 'thời thơ ấu, tuổi thơ', 'noun', '[{"en":"I spent most of my childhood in a small village.","vi":"Tôi đã trải qua phần lớn tuổi thơ ở một ngôi làng nhỏ."},{"en":"She has been my best friend since childhood.","vi":"Cô ấy là bạn thân nhất của tôi từ thuở nhỏ."},{"en":"These old songs bring back happy childhood memories.","vi":"Những bài hát cũ này gợi lại những kỷ niệm tuổi thơ vui vẻ."}]', '[{"phrase":"happy childhood"},{"phrase":"early childhood"},{"phrase":"childhood memories"},{"phrase":"since childhood"}]', NULL, '/ˈtʃaɪldhʊd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/chi/child/childhood__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 8, 'draft', 'bản nháp; bản thảo', 'noun', '[{"en":"Please send me the first draft of your report by Friday.","vi":"Vui lòng gửi cho tôi bản nháp đầu tiên của báo cáo trước thứ Sáu."},{"en":"I wrote three drafts before I was happy with the letter.","vi":"Tôi đã viết ba bản nháp rồi mới hài lòng với lá thư."},{"en":"The final draft looks much better than the earlier one.","vi":"Bản thảo cuối cùng trông tốt hơn nhiều so với bản trước."}]', '[{"phrase":"first draft"},{"phrase":"final draft"},{"phrase":"rough draft"}]', NULL, '/dræft/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dra/draft/draft__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 9, 'slip', 'trượt, trượt chân; lẻn, lặng lẽ đi', 'verb', '[{"en":"Be careful not to slip on the wet floor.","vi":"Cẩn thận kẻo trượt chân trên sàn ướt."},{"en":"She slipped on the ice and hurt her knee.","vi":"Cô ấy trượt chân trên băng và bị đau đầu gối."},{"en":"He slipped out of the meeting to answer a phone call.","vi":"Anh ấy lặng lẽ rời cuộc họp để nghe điện thoại."}]', '[{"phrase":"slip on"},{"phrase":"slip and fall"},{"phrase":"slip out"},{"phrase":"slip away"}]', 'slip – slipped – slipped', '/slɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sli/slip_/slip__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 10, 'accompany', 'đi cùng, đi kèm; đệm nhạc', 'verb', '[{"en":"Children under 12 must be accompanied by an adult.","vi":"Trẻ em dưới 12 tuổi phải có người lớn đi cùng."},{"en":"My mother accompanied me to the hospital yesterday.","vi":"Hôm qua mẹ tôi đã đi cùng tôi đến bệnh viện."},{"en":"She sang while her brother accompanied her on the piano.","vi":"Cô ấy hát trong khi anh trai đệm đàn piano cho cô."}]', '[{"phrase":"be accompanied by"},{"phrase":"accompany someone to"}]', 'accompany – accompanied – accompanied', '/əˈkʌmpəni/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accom/accompany__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 11, 'politician', 'chính trị gia, chính khách', 'noun', '[{"en":"Her father was a local politician for many years.","vi":"Bố cô ấy là một chính trị gia địa phương trong nhiều năm."},{"en":"The politician gave a short speech at the school opening.","vi":"Vị chính khách đã có bài phát biểu ngắn tại lễ khai trương trường."},{"en":"He wants to become a politician when he grows up.","vi":"Cậu ấy muốn trở thành chính trị gia khi lớn lên."}]', '[{"phrase":"local politician"},{"phrase":"senior politician"},{"phrase":"leading politician"}]', NULL, '/ˌpɑːləˈtɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pol/polit/politician__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 12, 'angry', 'tức giận, giận dữ', 'adjective', '[{"en":"My mom gets angry when I come home late.","vi":"Mẹ tôi nổi giận khi tôi về nhà muộn."},{"en":"Why are you so angry with me about this?","vi":"Sao bạn lại giận tôi vì chuyện này đến vậy?"},{"en":"Customers were angry about the long delay at the airport.","vi":"Khách hàng tức giận vì sự chậm trễ kéo dài ở sân bay."}]', '[{"phrase":"get angry"},{"phrase":"angry with"},{"phrase":"angry about"}]', 'angry with + người · angry about + sự việc', '/ˈæŋɡri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ang/angry/angry__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 13, 'knock', 'gõ (cửa); đụng, làm đổ', 'verb', '[{"en":"Please knock before you come into my room.","vi":"Làm ơn gõ cửa trước khi vào phòng tôi."},{"en":"Can you see who is knocking at the door?","vi":"Bạn xem ai đang gõ cửa được không?"},{"en":"The dog knocked over my cup of coffee this morning.","vi":"Sáng nay con chó làm đổ cốc cà phê của tôi."}]', '[{"phrase":"knock on the door"},{"phrase":"knock at the door"},{"phrase":"knock over"}]', NULL, '/nɑːk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kno/knock/knock__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 14, 'seed', 'hạt giống; hạt', 'noun', '[{"en":"We planted tomato seeds in the garden this spring.","vi":"Mùa xuân này chúng tôi đã gieo hạt cà chua trong vườn."},{"en":"These seeds need plenty of water and sunlight to grow.","vi":"Những hạt giống này cần nhiều nước và ánh nắng để phát triển."},{"en":"This watermelon has almost no seeds, so the kids love it.","vi":"Quả dưa hấu này gần như không có hạt nên bọn trẻ rất thích."}]', '[{"phrase":"plant seeds"},{"phrase":"sow seeds"},{"phrase":"sunflower seeds"}]', NULL, '/siːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/see/seed_/seed__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 15, 'salary', 'lương, tiền lương', 'noun', '[{"en":"She earns a good salary as a nurse.","vi":"Cô ấy nhận mức lương khá khi làm y tá."},{"en":"Our salaries are paid at the end of each month.","vi":"Lương của chúng tôi được trả vào cuối mỗi tháng."},{"en":"He asked for a higher salary after working there for two years.","vi":"Anh ấy đề nghị tăng lương sau khi làm việc ở đó hai năm."}]', '[{"phrase":"good salary"},{"phrase":"annual salary"},{"phrase":"earn a salary"},{"phrase":"salary increase"}]', NULL, '/ˈsæləri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sal/salar/salary__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 16, 'illustrate', 'minh họa; làm rõ, cho thấy', 'verb', '[{"en":"The teacher used a simple story to illustrate her point.","vi":"Cô giáo dùng một câu chuyện đơn giản để minh họa cho ý của mình."},{"en":"This chart illustrates how prices have changed over time.","vi":"Biểu đồ này cho thấy giá cả đã thay đổi thế nào theo thời gian."},{"en":"She illustrates children''s books for a living.","vi":"Cô ấy kiếm sống bằng nghề vẽ minh họa sách thiếu nhi."}]', '[{"phrase":"illustrate a point"},{"phrase":"clearly illustrate"},{"phrase":"illustrated book"}]', NULL, '/ˈɪləstreɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ill/illus/illustrate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 17, 'imply', 'ngụ ý, hàm ý', 'verb', '[{"en":"Are you implying that I made a mistake?","vi":"Bạn đang ngụ ý rằng tôi đã mắc lỗi à?"},{"en":"His silence implied that he did not agree with us.","vi":"Sự im lặng của anh ấy hàm ý rằng anh ấy không đồng ý với chúng tôi."},{"en":"The report implies that the company is losing money.","vi":"Bản báo cáo ngụ ý rằng công ty đang lỗ."}]', '[{"phrase":"imply that"},{"phrase":"clearly imply"},{"phrase":"strongly imply"}]', 'imply (người nói ngụ ý) ≠ infer (người nghe suy ra)', '/ɪmˈplaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/imply/imply__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 18, 'breakfast', 'bữa sáng', 'noun', '[{"en":"I usually have breakfast at seven before I go to work.","vi":"Tôi thường ăn sáng lúc bảy giờ trước khi đi làm."},{"en":"What did you eat for breakfast this morning?","vi":"Sáng nay bạn ăn gì vào bữa sáng?"},{"en":"She never skips breakfast, even when she is busy.","vi":"Cô ấy không bao giờ bỏ bữa sáng, kể cả khi bận rộn."}]', '[{"phrase":"have breakfast"},{"phrase":"for breakfast"},{"phrase":"skip breakfast"}]', NULL, '/ˈbrekfəst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bre/break/breakfast__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 19, 'temporary', 'tạm thời', 'adjective', '[{"en":"He found a temporary job during his summer vacation.","vi":"Anh ấy tìm được một công việc tạm thời trong kỳ nghỉ hè."},{"en":"The road is closed, but the problem is only temporary.","vi":"Con đường đang bị chặn, nhưng vấn đề này chỉ là tạm thời."},{"en":"We are living in a temporary apartment until our house is ready.","vi":"Chúng tôi đang ở một căn hộ tạm cho đến khi nhà xây xong."}]', '[{"phrase":"temporary job"},{"phrase":"temporary solution"},{"phrase":"temporary work"}]', NULL, '/ˈtempəreri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tem/tempo/temporary__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 20, 'liberal', 'cởi mở, phóng khoáng; hào phóng', 'adjective', '[{"en":"My grandparents are surprisingly liberal about many modern ideas.","vi":"Ông bà tôi cởi mở một cách đáng ngạc nhiên với nhiều quan niệm hiện đại."},{"en":"The school has a fairly liberal attitude toward uniforms.","vi":"Nhà trường có thái độ khá thoải mái về chuyện đồng phục."},{"en":"She was always liberal with her praise for her students.","vi":"Cô ấy luôn hào phóng lời khen dành cho học trò."}]', '[{"phrase":"liberal attitude"},{"phrase":"liberal views"},{"phrase":"liberal arts"}]', NULL, '/ˈlɪbərəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lib/liber/liberal__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 21, 'lake', 'hồ', 'noun', '[{"en":"We went swimming in the lake last summer.","vi":"Mùa hè năm ngoái chúng tôi đã đi bơi ở hồ."},{"en":"There is a small lake behind our village.","vi":"Có một cái hồ nhỏ phía sau làng chúng tôi."},{"en":"Our hotel room had a beautiful view of the lake.","vi":"Phòng khách sạn của chúng tôi có tầm nhìn đẹp ra hồ."}]', '[{"phrase":"swim in the lake"},{"phrase":"by the lake"},{"phrase":"frozen lake"}]', NULL, '/leɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lak/lake_/lake__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 22, 'qualify', 'đủ điều kiện; có đủ bằng cấp (hành nghề); giành quyền vào (vòng sau)', 'verb', '[{"en":"You may qualify for a discount if you are a student.","vi":"Nếu là sinh viên, bạn có thể đủ điều kiện được giảm giá."},{"en":"She qualified as a doctor after seven years of study.","vi":"Cô ấy có đủ bằng cấp hành nghề bác sĩ sau bảy năm học."},{"en":"Our team qualified for the final after winning today''s match.","vi":"Đội chúng tôi giành quyền vào chung kết sau khi thắng trận hôm nay."}]', '[{"phrase":"qualify for"},{"phrase":"qualify as"},{"phrase":"fully qualified"}]', 'qualify for + cái gì · qualify as + nghề', '/ˈkwɑːlɪfaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qua/quali/qualify__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 23, 'competitive', 'cạnh tranh; thích ganh đua', 'adjective', '[{"en":"The job market is very competitive for new graduates.","vi":"Thị trường việc làm rất cạnh tranh đối với sinh viên mới tốt nghiệp."},{"en":"This shop offers competitive prices on all its products.","vi":"Cửa hàng này có giá cả cạnh tranh cho mọi sản phẩm."},{"en":"My brother is so competitive that he hates losing at cards.","vi":"Anh tôi thích ganh đua đến mức rất ghét thua khi chơi bài."}]', '[{"phrase":"competitive prices"},{"phrase":"highly competitive"},{"phrase":"competitive market"}]', NULL, '/kəmˈpetətɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compe/competitive__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 24, 'truly', 'thật sự; thực lòng', 'adverb', '[{"en":"I am truly sorry for what I said yesterday.","vi":"Tôi thực lòng xin lỗi vì những gì mình nói hôm qua."},{"en":"It was a truly beautiful day at the beach.","vi":"Đó thật sự là một ngày đẹp trời ở bãi biển."},{"en":"Do you truly believe that he is telling the truth?","vi":"Bạn có thật sự tin rằng anh ta đang nói thật không?"}]', '[{"phrase":"truly sorry"},{"phrase":"truly believe"},{"phrase":"truly amazing"}]', NULL, '/ˈtruːli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tru/truly/truly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 25, 'hi', 'chào, xin chào', 'exclamation', '[{"en":"Hi, I''m your new neighbor from next door.","vi":"Chào bạn, tôi là hàng xóm mới ở nhà bên cạnh."},{"en":"Please say hi to your parents for me.","vi":"Cho tôi gửi lời chào đến bố mẹ bạn nhé."},{"en":"She smiled and said hi as she walked past.","vi":"Cô ấy mỉm cười và chào khi đi ngang qua."}]', '[{"phrase":"say hi"},{"phrase":"say hi to"},{"phrase":"hi there"}]', 'thân mật, dùng trong giao tiếp hằng ngày', '/haɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hi_/hi__u/hi__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 26, 'yellow', '(màu) vàng', 'adjective', '[{"en":"She wore a bright yellow dress to the party.","vi":"Cô ấy mặc một chiếc váy màu vàng tươi đến bữa tiệc."},{"en":"The leaves turn yellow before they fall from the trees.","vi":"Lá chuyển sang màu vàng trước khi rụng khỏi cây."},{"en":"Slow down when the traffic light turns yellow.","vi":"Hãy giảm tốc độ khi đèn giao thông chuyển sang vàng."}]', '[{"phrase":"bright yellow"},{"phrase":"pale yellow"},{"phrase":"turn yellow"}]', NULL, '/ˈjeləʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/y/yel/yello/yellow__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 27, 'habit', 'thói quen', 'noun', '[{"en":"Smoking is a bad habit that is hard to break.","vi":"Hút thuốc là một thói quen xấu khó bỏ."},{"en":"I''m trying to get into the habit of reading every night.","vi":"Tôi đang cố tạo thói quen đọc sách mỗi tối."},{"en":"He has a habit of biting his nails when he is nervous.","vi":"Anh ấy có thói quen cắn móng tay khi lo lắng."}]', '[{"phrase":"bad habit"},{"phrase":"break a habit"},{"phrase":"habit of"},{"phrase":"eating habits"}]', NULL, '/ˈhæbɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hab/habit/habit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 28, 'disk', 'đĩa, ổ đĩa (máy tính); vật hình đĩa', 'noun', '[{"en":"My computer is slow because the hard disk is almost full.","vi":"Máy tính của tôi chạy chậm vì ổ cứng gần đầy."},{"en":"The game came on a disk, but now you can download it.","vi":"Trò chơi này từng được bán trên đĩa, nhưng giờ bạn có thể tải về."},{"en":"The moon looked like a silver disk in the night sky.","vi":"Mặt trăng trông như một chiếc đĩa bạc trên bầu trời đêm."}]', '[{"phrase":"hard disk"},{"phrase":"disk space"},{"phrase":"disk drive"}]', 'Mỹ: disk · Anh: disc (máy tính thường viết disk)', '/dɪsk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disk_/disk__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 29, 'core', 'cốt lõi, trọng tâm; lõi', 'noun', '[{"en":"Honesty is at the core of a good friendship.","vi":"Sự trung thực là cốt lõi của một tình bạn đẹp."},{"en":"The core of the problem is a lack of money.","vi":"Mấu chốt của vấn đề là thiếu tiền."},{"en":"Please throw the apple core in the trash.","vi":"Làm ơn vứt lõi táo vào thùng rác."}]', '[{"phrase":"at the core of"},{"phrase":"the core of the problem"},{"phrase":"apple core"}]', NULL, '/kɔːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cor/core_/core__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-11', 30, 'emotional', '(thuộc) cảm xúc, tình cảm; xúc động', 'adjective', '[{"en":"She became very emotional when she said goodbye to her class.","vi":"Cô ấy rất xúc động khi chia tay lớp học của mình."},{"en":"Children need emotional support as well as good food.","vi":"Trẻ em cần sự hỗ trợ về mặt tình cảm cũng như thức ăn tốt."},{"en":"The movie has a very emotional ending.","vi":"Bộ phim có một cái kết rất xúc động."}]', '[{"phrase":"emotional support"},{"phrase":"emotional health"},{"phrase":"get emotional"}]', NULL, '/ɪˈməʊʃənl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emo/emoti/emotional__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-4-12', 'ngsl-4', 'Thông dụng 1.501–2.000 · Bộ 12', 'New General Service List, thứ hạng 1.501–2.000', '#3da9fc', 'BookOpen', 12);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 1, 'aircraft', 'máy bay; phi cơ', 'noun', '[{"en":"The aircraft landed safely despite the strong wind.","vi":"Chiếc máy bay đã hạ cánh an toàn dù gió mạnh."},{"en":"All passengers must stay seated until the aircraft stops completely.","vi":"Tất cả hành khách phải ngồi yên cho đến khi máy bay dừng hẳn."},{"en":"My uncle has repaired military aircraft for over twenty years.","vi":"Chú tôi đã sửa chữa máy bay quân sự hơn hai mươi năm."}]', '[{"phrase":"military aircraft"},{"phrase":"board an aircraft"},{"phrase":"aircraft carrier"}]', 'Số nhiều không đổi: one aircraft – two aircraft', '/ˈerkræft/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/air/aircr/aircraft__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 2, 'self', 'bản thân; con người (của ai)', 'noun', '[{"en":"After a good night''s sleep, she felt like her old self again.","vi":"Sau một đêm ngủ ngon, cô ấy lại thấy mình như trước đây."},{"en":"With close friends, she finally feels free to show her true self.","vi":"Khi ở bên bạn thân, cô ấy cuối cùng cũng thấy thoải mái thể hiện con người thật của mình."},{"en":"He seemed tired and was not his usual cheerful self.","vi":"Anh ấy có vẻ mệt và không vui vẻ như thường ngày."}]', '[{"phrase":"sense of self"},{"phrase":"your old self"},{"phrase":"your true self"}]', 'Số nhiều: selves', '/self/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sel/self_/self__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 3, 'metal', 'kim loại', 'noun', '[{"en":"Gold and silver are both expensive metals.","vi":"Vàng và bạc đều là những kim loại đắt tiền."},{"en":"The chairs in the garden are made of metal.","vi":"Những chiếc ghế trong vườn được làm bằng kim loại."},{"en":"Don''t put metal dishes in the microwave.","vi":"Đừng cho bát đĩa bằng kim loại vào lò vi sóng."}]', '[{"phrase":"made of metal"},{"phrase":"precious metal"},{"phrase":"sheet of metal"},{"phrase":"metal box"}]', NULL, '/ˈmetl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/met/metal/metal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 4, 'existence', 'sự tồn tại; cuộc sống', 'noun', '[{"en":"Many people still doubt the existence of life on other planets.","vi":"Nhiều người vẫn nghi ngờ sự tồn tại của sự sống trên các hành tinh khác."},{"en":"This small bakery has been in existence for over fifty years.","vi":"Tiệm bánh nhỏ này đã tồn tại hơn năm mươi năm."},{"en":"My grandparents lived a quiet, simple existence in the village.","vi":"Ông bà tôi sống một cuộc sống yên bình, giản dị ở làng quê."}]', '[{"phrase":"in existence"},{"phrase":"come into existence"},{"phrase":"the existence of"}]', NULL, '/ɪɡˈzɪstəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exi/exist/existence__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 5, 'bone', 'xương', 'noun', '[{"en":"He broke a bone in his foot while playing football.","vi":"Anh ấy bị gãy một chiếc xương ở bàn chân khi chơi bóng đá."},{"en":"Be careful, this fish still has a lot of small bones.","vi":"Cẩn thận nhé, con cá này vẫn còn nhiều xương nhỏ."},{"en":"Our dog buried a bone somewhere in the backyard.","vi":"Con chó nhà tôi đã chôn một khúc xương đâu đó ở sân sau."}]', '[{"phrase":"break a bone"},{"phrase":"broken bone"},{"phrase":"fish bone"}]', NULL, '/bəʊn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bon/bone_/bone__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 6, 'panel', 'ban, nhóm (chuyên gia); tấm (ván, kính); bảng điều khiển', 'noun', '[{"en":"A panel of experts will choose the winner of the contest.","vi":"Một ban chuyên gia sẽ chọn ra người thắng cuộc thi."},{"en":"We installed solar panels on the roof last summer.","vi":"Mùa hè năm ngoái chúng tôi đã lắp tấm pin mặt trời trên mái nhà."},{"en":"A red light started flashing on the control panel.","vi":"Một đèn đỏ bắt đầu nhấp nháy trên bảng điều khiển."}]', '[{"phrase":"panel of experts"},{"phrase":"solar panel"},{"phrase":"control panel"},{"phrase":"panel discussion"}]', NULL, '/ˈpænl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pan/panel/panel__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 7, 'prime', 'chính, hàng đầu; tốt nhất', 'adjective', '[{"en":"Cost was our prime concern when choosing a new apartment.","vi":"Chi phí là mối quan tâm hàng đầu của chúng tôi khi chọn căn hộ mới."},{"en":"The hotel is in a prime location near the beach.","vi":"Khách sạn nằm ở vị trí đắc địa gần bãi biển."},{"en":"Poor diet is a prime cause of many health problems.","vi":"Chế độ ăn uống kém là nguyên nhân chính của nhiều vấn đề sức khỏe."}]', '[{"phrase":"prime minister"},{"phrase":"prime location"},{"phrase":"prime example"},{"phrase":"prime concern"}]', NULL, '/praɪm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/prime/prime__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 8, 'appointment', 'cuộc hẹn; sự bổ nhiệm', 'noun', '[{"en":"I have a dentist appointment at three this afternoon.","vi":"Chiều nay lúc ba giờ tôi có hẹn với nha sĩ."},{"en":"Please call ahead to make an appointment with the doctor.","vi":"Vui lòng gọi trước để đặt lịch hẹn với bác sĩ."},{"en":"Everyone was happy about her appointment as team leader.","vi":"Mọi người đều vui vì cô ấy được bổ nhiệm làm trưởng nhóm."}]', '[{"phrase":"make an appointment"},{"phrase":"cancel an appointment"},{"phrase":"doctor''s appointment"},{"phrase":"by appointment"}]', NULL, '/əˈpɔɪntmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appoi/appointment__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 9, 'emphasize', 'nhấn mạnh', 'verb', '[{"en":"The teacher emphasized the importance of reading every day.","vi":"Giáo viên nhấn mạnh tầm quan trọng của việc đọc mỗi ngày."},{"en":"I want to emphasize that this offer ends on Friday.","vi":"Tôi muốn nhấn mạnh rằng ưu đãi này kết thúc vào thứ Sáu."},{"en":"She wore a belt to emphasize her small waist.","vi":"Cô ấy thắt dây lưng để làm nổi bật vòng eo nhỏ."}]', '[{"phrase":"emphasize the importance of"},{"phrase":"emphasize that"},{"phrase":"strongly emphasize"}]', 'Anh: emphasise · Mỹ: emphasize', '/ˈemfəsaɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emp/empha/emphasize__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 10, 'maximum', 'mức tối đa; tối đa', 'noun', '[{"en":"The maximum speed on this road is sixty kilometers an hour.","vi":"Tốc độ tối đa trên con đường này là sáu mươi ki-lô-mét một giờ."},{"en":"Each passenger can bring a maximum of two bags.","vi":"Mỗi hành khách được mang tối đa hai túi."},{"en":"Turn the volume up to maximum so everyone can hear.","vi":"Hãy vặn âm lượng lên mức tối đa để mọi người đều nghe được."}]', '[{"phrase":"maximum speed"},{"phrase":"a maximum of"},{"phrase":"maximum number"},{"phrase":"maximum temperature"}]', 'Trái nghĩa: minimum', '/ˈmæksɪməm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/max/maxim/maximum__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 11, 'effectively', 'một cách hiệu quả; thực tế là', 'adverb', '[{"en":"Good managers know how to communicate effectively with their teams.","vi":"Người quản lý giỏi biết cách giao tiếp hiệu quả với đội của mình."},{"en":"This cream works effectively against dry skin.","vi":"Loại kem này có tác dụng hiệu quả với da khô."},{"en":"The road was closed, so the village was effectively cut off.","vi":"Con đường bị đóng, nên thực tế là ngôi làng bị cô lập."}]', '[{"phrase":"work effectively"},{"phrase":"communicate effectively"},{"phrase":"use something effectively"}]', NULL, '/ɪˈfektɪvli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eff/effec/effectively__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 12, 'elsewhere', 'ở nơi khác; đến nơi khác', 'adverb', '[{"en":"This shop is too expensive, so let''s look elsewhere.","vi":"Cửa hàng này đắt quá, mình tìm chỗ khác đi."},{"en":"Prices here are lower than elsewhere in the city.","vi":"Giá ở đây rẻ hơn những nơi khác trong thành phố."},{"en":"If you are not happy, you can take your business elsewhere.","vi":"Nếu không hài lòng, bạn có thể đi mua ở nơi khác."}]', '[{"phrase":"look elsewhere"},{"phrase":"go elsewhere"},{"phrase":"elsewhere in the world"}]', NULL, '/ˌelsˈwer/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/els/elsew/elsewhere__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 13, 'bother', 'làm phiền; bận tâm, mất công', 'verb', '[{"en":"Sorry to bother you, but could you help me with this?","vi":"Xin lỗi đã làm phiền bạn, nhưng bạn có thể giúp tôi việc này không?"},{"en":"Does the noise from the street bother you at night?","vi":"Tiếng ồn ngoài đường có làm bạn khó chịu vào ban đêm không?"},{"en":"He didn''t even bother to say goodbye before he left.","vi":"Anh ta thậm chí chẳng buồn chào tạm biệt trước khi đi."}]', '[{"phrase":"sorry to bother you"},{"phrase":"don''t bother"},{"phrase":"bother to do something"}]', NULL, '/ˈbɑːðər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bot/bothe/bother__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 14, 'initiative', 'sáng kiến; tính chủ động', 'noun', '[{"en":"The city launched a new initiative to plant more trees.","vi":"Thành phố đã khởi động một sáng kiến mới để trồng thêm cây xanh."},{"en":"She took the initiative and organized the team meeting herself.","vi":"Cô ấy đã chủ động tự tổ chức buổi họp nhóm."},{"en":"Our boss wants staff who show initiative at work.","vi":"Sếp chúng tôi muốn những nhân viên thể hiện tính chủ động trong công việc."}]', '[{"phrase":"take the initiative"},{"phrase":"show initiative"},{"phrase":"new initiative"},{"phrase":"on your own initiative"}]', NULL, '/ɪˈnɪʃətɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ini/initi/initiative__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 15, 'sharp', 'sắc, nhọn; đột ngột; thông minh', 'adjective', '[{"en":"Be careful, that kitchen knife is very sharp.","vi":"Cẩn thận nhé, con dao làm bếp đó rất sắc."},{"en":"There has been a sharp rise in house prices this year.","vi":"Năm nay giá nhà đã tăng mạnh đột ngột."},{"en":"My grandmother is ninety, but her mind is still sharp.","vi":"Bà tôi đã chín mươi tuổi nhưng đầu óc vẫn còn minh mẫn."}]', '[{"phrase":"sharp knife"},{"phrase":"sharp rise"},{"phrase":"sharp pain"},{"phrase":"sharp mind"}]', 'at six o''clock sharp = đúng sáu giờ', '/ʃɑːrp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sha/sharp/sharp__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 16, 'diet', 'chế độ ăn uống; chế độ ăn kiêng', 'noun', '[{"en":"A healthy diet includes plenty of fruit and vegetables.","vi":"Một chế độ ăn uống lành mạnh gồm nhiều trái cây và rau củ."},{"en":"I''m on a diet, so no cake for me, thanks.","vi":"Tôi đang ăn kiêng, nên cho tôi xin không ăn bánh nhé."},{"en":"The doctor told him to change his diet and exercise more.","vi":"Bác sĩ bảo anh ấy thay đổi chế độ ăn và tập thể dục nhiều hơn."}]', '[{"phrase":"healthy diet"},{"phrase":"balanced diet"},{"phrase":"on a diet"},{"phrase":"go on a diet"}]', NULL, '/ˈdaɪət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/die/diet_/diet__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 17, 'motion', 'sự chuyển động; cử chỉ; kiến nghị', 'noun', '[{"en":"Do not open the door while the train is in motion.","vi":"Không được mở cửa khi tàu đang chạy."},{"en":"The motion of the boat made me feel sick.","vi":"Sự chòng chành của con thuyền làm tôi thấy buồn nôn."},{"en":"The committee voted in favor of the motion.","vi":"Ủy ban đã bỏ phiếu tán thành bản kiến nghị."}]', '[{"phrase":"in motion"},{"phrase":"slow motion"},{"phrase":"motion sickness"},{"phrase":"set something in motion"}]', NULL, '/ˈməʊʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mot/motio/motion__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 18, 'gray', '(màu) xám; (tóc) bạc', 'adjective', '[{"en":"The sky turned gray, and it started to rain.","vi":"Bầu trời chuyển sang màu xám, rồi trời bắt đầu mưa."},{"en":"My father''s hair went gray when he was only forty.","vi":"Tóc bố tôi đã bạc khi ông mới bốn mươi tuổi."},{"en":"She bought a dark gray coat for the winter.","vi":"Cô ấy mua một chiếc áo khoác màu xám đậm cho mùa đông."}]', '[{"phrase":"gray hair"},{"phrase":"go gray"},{"phrase":"dark gray"},{"phrase":"gray sky"}]', 'Mỹ: gray · Anh: grey', '/ɡreɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/gray_/gray__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 19, 'plastic', 'nhựa; (bằng) nhựa', 'noun', '[{"en":"Many countries are trying to use less plastic.","vi":"Nhiều quốc gia đang cố gắng dùng ít nhựa hơn."},{"en":"Please bring your own bag instead of taking a plastic one.","vi":"Vui lòng mang túi riêng thay vì lấy túi nhựa."},{"en":"These toys are made of plastic, so they won''t break easily.","vi":"Những món đồ chơi này làm bằng nhựa nên không dễ vỡ."}]', '[{"phrase":"plastic bag"},{"phrase":"plastic bottle"},{"phrase":"made of plastic"},{"phrase":"plastic waste"}]', NULL, '/ˈplæstɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/plast/plastic__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 20, 'complicate', 'làm phức tạp', 'verb', '[{"en":"Let''s not complicate things by adding more rules.","vi":"Chúng ta đừng làm mọi chuyện phức tạp bằng cách thêm quy định."},{"en":"The bad weather complicated our travel plans.","vi":"Thời tiết xấu đã làm kế hoạch đi du lịch của chúng tôi thêm phức tạp."},{"en":"His illness was complicated by a serious infection.","vi":"Bệnh của anh ấy trở nên phức tạp hơn do một ca nhiễm trùng nặng."}]', '[{"phrase":"complicate matters"},{"phrase":"complicate things"},{"phrase":"further complicate"}]', NULL, '/ˈkɑːmplɪkeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compl/complicate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 21, 'discipline', 'kỷ luật; sự rèn luyện', 'noun', '[{"en":"Learning a language takes time and a lot of discipline.","vi":"Học một ngôn ngữ cần thời gian và rất nhiều kỷ luật."},{"en":"The new teacher had trouble keeping discipline in the classroom.","vi":"Giáo viên mới gặp khó khăn trong việc giữ kỷ luật trong lớp."},{"en":"Some parents believe discipline should start at a very young age.","vi":"Một số bậc cha mẹ tin rằng việc rèn kỷ luật nên bắt đầu từ khi còn rất nhỏ."}]', '[{"phrase":"self-discipline"},{"phrase":"strict discipline"},{"phrase":"maintain discipline"},{"phrase":"lack of discipline"}]', NULL, '/ˈdɪsəplɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disci/discipline__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 22, 'disappoint', 'làm thất vọng', 'verb', '[{"en":"I''m sorry to disappoint you, but the tickets are sold out.","vi":"Rất tiếc phải làm bạn thất vọng, nhưng vé đã bán hết rồi."},{"en":"The movie was good, but the ending disappointed me.","vi":"Bộ phim hay, nhưng cái kết làm tôi thất vọng."},{"en":"She worked hard because she didn''t want to disappoint her parents.","vi":"Cô ấy học hành chăm chỉ vì không muốn làm bố mẹ thất vọng."}]', '[{"phrase":"sorry to disappoint you"},{"phrase":"disappoint your parents"},{"phrase":"won''t disappoint"}]', NULL, '/ˌdɪsəˈpɔɪnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disap/disappoint__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 23, 'boss', 'sếp; ông chủ', 'noun', '[{"en":"I need to ask my boss for a day off.","vi":"Tôi cần xin sếp cho nghỉ một ngày."},{"en":"Her new boss is friendly and easy to talk to.","vi":"Sếp mới của cô ấy thân thiện và dễ nói chuyện."},{"en":"He wants to start his own company and be his own boss.","vi":"Anh ấy muốn mở công ty riêng và tự làm chủ."}]', '[{"phrase":"your boss"},{"phrase":"new boss"},{"phrase":"be your own boss"}]', NULL, '/bɔːs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bos/boss_/boss__us_8.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 24, 'assumption', 'giả định; sự cho rằng', 'noun', '[{"en":"Don''t make assumptions about people based on how they look.","vi":"Đừng phỏng đoán về người khác dựa trên vẻ ngoài của họ."},{"en":"We planned the budget on the assumption that prices would stay the same.","vi":"Chúng tôi lập ngân sách với giả định rằng giá cả sẽ giữ nguyên."},{"en":"My assumption was wrong, and the store was open after all.","vi":"Tôi đã đoán sai, hóa ra cửa hàng vẫn mở."}]', '[{"phrase":"make an assumption"},{"phrase":"on the assumption that"},{"phrase":"wrong assumption"},{"phrase":"basic assumption"}]', NULL, '/əˈsʌmpʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assum/assumption__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 25, 'freeze', 'đóng băng; đông lạnh; đứng sững lại', 'verb', '[{"en":"It was so cold last night that the lake froze over.","vi":"Đêm qua trời lạnh đến mức mặt hồ đóng băng hết."},{"en":"You can freeze the leftover soup and eat it next week.","vi":"Bạn có thể cấp đông phần súp còn thừa và ăn vào tuần sau."},{"en":"She froze when she heard a strange noise downstairs.","vi":"Cô ấy đứng sững lại khi nghe thấy tiếng động lạ dưới nhà."}]', '[{"phrase":"freeze to death"},{"phrase":"freeze food"},{"phrase":"freeze prices"}]', 'freeze – froze – frozen', '/friːz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fre/freez/freeze__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 26, 'extreme', 'cực độ, khắc nghiệt; quá khích', 'adjective', '[{"en":"Plants in the desert can survive extreme heat.","vi":"Thực vật ở sa mạc có thể sống sót trong cái nóng khắc nghiệt."},{"en":"Please drive with extreme care on icy roads.","vi":"Vui lòng lái xe hết sức cẩn thận trên đường đóng băng."},{"en":"I think his views on money are a bit extreme.","vi":"Tôi nghĩ quan điểm của anh ấy về tiền bạc hơi cực đoan."}]', '[{"phrase":"extreme heat"},{"phrase":"extreme weather"},{"phrase":"extreme care"},{"phrase":"extreme case"}]', NULL, '/ɪkˈstriːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/extre/extreme__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 27, 'passage', 'đoạn văn; lối đi, hành lang', 'noun', '[{"en":"Read the passage and answer the questions below.","vi":"Hãy đọc đoạn văn và trả lời các câu hỏi bên dưới."},{"en":"The teacher asked me to read a short passage aloud.","vi":"Cô giáo bảo tôi đọc to một đoạn văn ngắn."},{"en":"A narrow passage leads from the kitchen to the garden.","vi":"Một lối đi hẹp dẫn từ nhà bếp ra vườn."}]', '[{"phrase":"reading passage"},{"phrase":"short passage"},{"phrase":"narrow passage"},{"phrase":"read a passage"}]', NULL, '/ˈpæsɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pas/passa/passage__us_5.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 28, 'reputation', 'danh tiếng, tiếng tăm', 'noun', '[{"en":"This restaurant has a good reputation for fresh seafood.","vi":"Nhà hàng này nổi tiếng về hải sản tươi ngon."},{"en":"One bad review can damage a small company''s reputation.","vi":"Một đánh giá xấu có thể làm tổn hại danh tiếng của một công ty nhỏ."},{"en":"She has built a reputation as a reliable and honest worker.","vi":"Cô ấy đã gây dựng được tiếng là một nhân viên đáng tin cậy và trung thực."}]', '[{"phrase":"good reputation"},{"phrase":"reputation for"},{"phrase":"damage your reputation"},{"phrase":"build a reputation"}]', NULL, '/ˌrepjuˈteɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rep/reput/reputation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 29, 'forth', 'về phía trước, qua lại; trở đi', 'adverb', '[{"en":"He walked back and forth while waiting for the phone call.","vi":"Anh ấy đi đi lại lại trong lúc chờ cuộc điện thoại."},{"en":"We need pens, paper, folders and so forth for the office.","vi":"Văn phòng cần bút, giấy, bìa hồ sơ, v.v."},{"en":"From that day forth, she never missed a single class.","vi":"Từ ngày đó trở đi, cô ấy không bỏ một buổi học nào."}]', '[{"phrase":"back and forth"},{"phrase":"and so forth"},{"phrase":"from that day forth"},{"phrase":"set forth"}]', NULL, '/fɔːrθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forth/forth__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-12', 30, 'negotiation', 'sự đàm phán, thương lượng', 'noun', '[{"en":"After long negotiations, the two companies finally signed the deal.","vi":"Sau những cuộc đàm phán kéo dài, hai công ty cuối cùng đã ký hợp đồng."},{"en":"The price of the car is open to negotiation.","vi":"Giá của chiếc xe này có thể thương lượng."},{"en":"Good negotiation skills are useful when you ask for a raise.","vi":"Kỹ năng đàm phán tốt rất hữu ích khi bạn xin tăng lương."}]', '[{"phrase":"open to negotiation"},{"phrase":"negotiation skills"},{"phrase":"under negotiation"},{"phrase":"enter into negotiations"}]', NULL, '/nɪˌɡəʊʃiˈeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/neg/negot/negotiation__us_1.mp3', NULL, NULL);
